/** Public entry point: the only module consumers and docs import from. */
export { useDataGridComments } from "./use-data-grid-comments";
export type { DataGridCommentsLabels } from "./labels";
export type {
  ApplyRemoteSkipReason,
  ApplyRemoteVerdict,
  CellComment,
  CommentAction,
  CommentAuthor,
  CommentChange,
  CommentCreateGateCtx,
  CommentFetchCtx,
  CommentFetchErrorCtx,
  CommentGateCtx,
  CommentMenuItem,
  CommentMenuItemsResolver,
  CommentRejectedCtx,
  CommentRejectReason,
  CommentSaveAck,
  CommentSaveCtx,
  CommentSaveRejectReason,
  CommentSaveResult,
  CommentSource,
  CommentsChangeCtx,
  OrphanedCommentsCtx,
  UseDataGridCommentsOptions,
  UseDataGridCommentsResult,
} from "./types";

// Relative on purpose: the shadcn CLI rewrites import paths, never augmentation module names.
declare module "../data-grid/types" {
  interface GridActions {
    openComments: true;
  }
}

"use client";

import { useEffect, useState } from "react";
import type { DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import { createCommentEngine, type CommentEngine } from "./comment-engine";
import { createCommentsMount } from "./comments-mount";
import { createCommentsOverlay } from "./comments-overlay";
import { createMenuItemsResolver } from "./menu-items";
import type { UseDataGridCommentsOptions, UseDataGridCommentsResult } from "./types";

const RENDER_OPTION_KEYS = ["hideResolved", "labels", "className", "allowWhenReadOnly", "canEdit", "canDelete", "canResolve", "canCreate", "fetchComments"] as const;

function renderOptionsChanged(previous: UseDataGridCommentsOptions, next: UseDataGridCommentsOptions): boolean {
  if (previous.currentUser?.id !== next.currentUser?.id || previous.currentUser?.name !== next.currentUser?.name) return true;
  return RENDER_OPTION_KEYS.some((key) => previous[key] !== next[key]);
}

type Instance = {
  engine: CommentEngine;
  /** The latest options and the last controlled prop; written in an effect, read by callbacks. */
  live: { options: UseDataGridCommentsOptions; prop: UseDataGridCommentsOptions["comments"] };
  result: UseDataGridCommentsResult;
};

type Live = Instance["live"];

function assignOptions(live: Live, options: UseDataGridCommentsOptions): UseDataGridCommentsOptions {
  const previous = live.options;
  live.options = options;
  return previous;
}

function previousProp(live: Live): UseDataGridCommentsOptions["comments"] {
  return live.prop;
}

function assignProp(live: Live, prop: UseDataGridCommentsOptions["comments"]): void {
  live.prop = prop;
}

function createInstance(options: UseDataGridCommentsOptions): Instance {
  const live = { options, prop: options.comments };
  const getOptions = (): UseDataGridCommentsOptions => live.options;
  const engine = createCommentEngine({
    getOptions,
    controlled: options.comments !== undefined,
    initialComments: options.comments ?? options.defaultComments,
  });
  const plugin: DataGridPlugin = {
    name: "comments",
    Overlay: createCommentsOverlay(engine, getOptions),
    Mount: createCommentsMount(engine, getOptions),
    onDataChange: (next, change, ctx) => engine.observeDataChange(next, change, { getRowId: ctx.api.store.getState().getRowId }),
    commands: {
      openComments: {
        when: (ctx) => ctx.row !== undefined && ctx.cell !== null,
        run: (ctx) => {
          if (ctx.cell) engine.openComments(ctx.cell, "keyboard");
        },
      },
    },
    keymap: { openComments: ["shift+F2"] },
  };
  const result: UseDataGridCommentsResult = {
    plugin,
    applyRemote: engine.applyRemote,
    getComments: engine.getComments,
    removeComments: (target) => engine.removeComments(target.rowIds),
    refetchComments: (target) => engine.refetch(target?.rowIds),
    openComments: (ref) => engine.openComments(ref, "keyboard"),
    closeComments: () => engine.store.close(),
    getCommentMenuItems: createMenuItemsResolver(engine, getOptions),
  };
  return { engine, live, result };
}

/**
 * Cell comments as a single hook: markers, the comments popover, optimistic writes with versions,
 * and echo handling. The hook is called outside the provider; pass `plugin` to the grid's `plugins`.
 * The app owns transport and save (`onCommentSave`, `applyRemote`, `fetchComments`).
 */
export function useDataGridComments(options: UseDataGridCommentsOptions = {}): UseDataGridCommentsResult {
  const [instance] = useState(() => createInstance(options));
  const { engine, live } = instance;

  useEffect(() => {
    const previous = assignOptions(live, options);
    if (renderOptionsChanged(previous, options)) engine.store.bumpContent();
    if (options.comments !== undefined && options.comments !== previousProp(live)) {
      assignProp(live, options.comments);
      engine.syncProp(options.comments);
    }
  });

  useEffect(() => {
    engine.start();
    return () => engine.dispose();
  }, [engine]);

  return instance.result;
}

import type { DataChange, DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import type { DataGridCommentsLabels } from "./labels";

/** Who wrote or resolved a comment. The server should set it from the session; the add-on shows it as given. */
export type CommentAuthor = {
  /** 1..128 characters, no control characters. */
  id: string;
  /** Display name, at most 80 characters; control and bidi-override characters are stripped. */
  name?: string;
  /** CSS color of the author chip, at most 64 characters; an invalid color falls back to a theme token. */
  color?: string;
};

/** One comment on one cell. The cell is addressed by `rowId` and `columnId`, never by a view index. */
export type CellComment = {
  /** Client-generated key (`createId`); the permanent identity and the create idempotency key. */
  id: string;
  rowId: string;
  columnId: string;
  /** 1..`maxTextLength` characters after trim. */
  text: string;
  author: CommentAuthor;
  /** Epoch milliseconds. */
  createdAt: number;
  /** Epoch milliseconds; the server should stamp it. */
  updatedAt: number;
  /** Integer 1..1,000,000,000; +1 per accepted write (a stamping server may return a higher one). */
  version: number;
  /** Id of the write that produced this version; generated by the add-on. */
  writeId?: string;
  resolved: boolean;
  resolvedBy?: CommentAuthor;
  resolvedAt?: number;
};

/** One write as a transport sees it. Resolve and reopen are `upsert` with `resolved` changed. A delete is a tombstone. */
export type CommentChange =
  | { kind: "upsert"; comment: CellComment; baseVersion?: number }
  | { kind: "delete"; id: string; rowId: string; columnId: string; version: number; writeId?: string; baseVersion?: number };

/** What made a store write: an acknowledgement, a remote batch, a fetch answer, a row id swap, or `removeComments`. */
export type CommentSource = "ack" | "remote" | "fetch" | "id-swap" | "remove";

/** What a comment write does. */
export type CommentAction = "create" | "update" | "delete" | "resolve" | "reopen";

/** Context of `onCommentsChange`. */
export type CommentsChangeCtx = { changes: readonly CommentChange[]; source: CommentSource };

/** Context of `onCommentSave`. */
export type CommentSaveCtx = {
  action: CommentAction;
  /** Carries `baseVersion`, `writeId`, and the new record. */
  change: CommentChange;
  /** The last confirmed record before the write. */
  prev?: CellComment;
};

/** Reasons a transport may reject a write with. */
export type CommentSaveRejectReason = "stale" | "forbidden" | "invalid" | "limit";

/** What `onCommentSave` may answer. */
export type CommentSaveAck =
  | { comment?: CellComment | null }
  | { rejected: { reason: CommentSaveRejectReason; message?: string; current?: CellComment | null } };

/** Return type of `onCommentSave`: `void` accepts the write exactly as sent. */
export type CommentSaveResult = void | CommentSaveAck | Promise<void | CommentSaveAck>;

/** Every reason a write is refused or reverted. */
export type CommentRejectReason = CommentSaveRejectReason | "read-only" | "row-busy" | "error";

/** Context of `onCommentRejected`. */
export type CommentRejectedCtx = {
  action: CommentAction;
  /** Absent when the write was refused before a record existed (invalid `createId` or `currentUser`). */
  change?: CommentChange;
  reason: CommentRejectReason;
  message?: string;
  current?: CellComment | null;
  error?: unknown;
};

/** Context of the `canEdit`, `canDelete`, and `canResolve` gates. `signal` aborts on unmount or when the request is superseded. */
export type CommentGateCtx = { comment: CellComment; user: CommentAuthor; signal: AbortSignal };

/** Context of the `canCreate` gate. */
export type CommentCreateGateCtx = { rowId: string; columnId: string; user: CommentAuthor; signal: AbortSignal };

/** Context of `fetchComments`. */
export type CommentFetchCtx = { rowIds: readonly string[]; signal: AbortSignal };

/** Context of `onFetchError`. */
export type CommentFetchErrorCtx = { reason: "error" | "limit"; rowIds: readonly string[]; error?: unknown };

/** Context of `onOrphanedComments`: comments whose rows were deleted. They stay in the store. */
export type OrphanedCommentsCtx = { comments: readonly CellComment[]; rowIds: readonly string[]; source: DataChange<unknown>["source"] };

/** Why `applyRemote` skipped a change. */
export type ApplyRemoteSkipReason = "stale" | "duplicate" | "invalid" | "limit" | "tombstoned" | "unknown";

/** What `applyRemote` did with a batch. */
export type ApplyRemoteVerdict = {
  applied: number;
  skippedCount: number;
  /** The first 100 skipped changes. */
  skipped: readonly { index: number; reason: ApplyRemoteSkipReason }[];
  /** Changes beyond the batch limit, ignored. */
  truncated: number;
};

/** The context-menu item shape the add-on contributes. */
export type CommentMenuItem = {
  id: string;
  label: string;
  onClick: () => void;
};

/** Structurally compatible with the context-menu add-on's `CellMenuItemsResolver`; pass it as `getCellMenuItems`. */
export type CommentMenuItemsResolver = <TItem extends { id: string }>(
  ctx: { rowId: string; columnId: string; viewRowIndex: number },
  defaults: TItem[],
) => (TItem | CommentMenuItem)[];

/** Options of {@link useDataGridComments}. */
export type UseDataGridCommentsOptions = {
  /** The user who writes. Without it the popover is read-only. */
  currentUser?: CommentAuthor;
  /** Controlled confirmed comments. Keep the reference stable between renders. */
  comments?: readonly CellComment[];
  /** One-shot seed. */
  defaultComments?: readonly CellComment[];
  /** State channel: one call per store write, `next` holds confirmed records only. With `fetchComments` it is a partial cache: save from `ctx.changes`. */
  onCommentsChange?: (next: readonly CellComment[], ctx: CommentsChangeCtx) => void;
  /** Saves one write. Return nothing to accept it as sent, `{ comment }` for the authoritative record, `{ rejected }` or throw to revert. */
  onCommentSave?: (ctx: CommentSaveCtx) => CommentSaveResult;
  /** Called once per refused or reverted write. */
  onCommentRejected?: (ctx: CommentRejectedCtx) => void;
  /** Broadcast seam: fires once per confirmed local write. It cannot refuse. */
  onLocalChange?: (change: CommentChange) => void;
  /** Gate for creating a comment. Default: anyone. */
  canCreate?: (ctx: CommentCreateGateCtx) => boolean | Promise<boolean>;
  /** Gate for editing. Default: the author. */
  canEdit?: (ctx: CommentGateCtx) => boolean | Promise<boolean>;
  /** Gate for deleting. Default: the author. */
  canDelete?: (ctx: CommentGateCtx) => boolean | Promise<boolean>;
  /** Gate for resolving and reopening. Default: anyone. */
  canResolve?: (ctx: CommentGateCtx) => boolean | Promise<boolean>;
  /** Loads the comments of the rendered rows. */
  fetchComments?: (ctx: CommentFetchCtx) => Promise<readonly CellComment[]>;
  /** Called for a failed fetch request or for records dropped for a bound. */
  onFetchError?: (ctx: CommentFetchErrorCtx) => void;
  /** Called when rows with comments are deleted. */
  onOrphanedComments?: (ctx: OrphanedCommentsCtx) => void;
  /** Default: `crypto.randomUUID` with a fallback outside secure contexts. */
  createId?: () => string;
  /** Applied to local text before the bounds are checked. */
  normalizeText?: (text: string) => string;
  /** Default 2,000; ceiling 20,000. */
  maxTextLength?: number;
  /** Default 50; ceiling 500. */
  maxCommentsPerCell?: number;
  /** Default 50,000; ceiling 500,000. */
  maxComments?: number;
  /** Uncontrolled fetch cache bound in rows. Default 2,000; ceiling 20,000. */
  maxCachedRows?: number;
  /** Let comment writes through on a `readOnly` grid. Default `false`. */
  allowWhenReadOnly?: boolean;
  /** Hide the markers of resolved-only cells. Default `false`. */
  hideResolved?: boolean;
  /** Overrides the strings of the comments UI. A key set to `undefined` keeps its default. */
  labels?: Partial<DataGridCommentsLabels>;
  /** Class of the popover root, merged with `cn`. */
  className?: string;
};

/** Return value of {@link useDataGridComments}. */
export type UseDataGridCommentsResult = {
  /** One entry of the grid's `plugins`. Stable for the component's lifetime. */
  plugin: DataGridPlugin;
  /** Applies records another client wrote. Works in controlled and uncontrolled mode. */
  applyRemote(changes: readonly CommentChange[]): ApplyRemoteVerdict;
  /** A bounded snapshot, not reactive. Partial under the fetch cache. */
  getComments(): readonly CellComment[];
  /** Forgets the comments of these rows (emits `onCommentsChange` with source `"remove"`). Returns how many were removed. */
  removeComments(target: { rowIds: readonly string[] }): number;
  /** Marks rows unfetched and loads them again. */
  refetchComments(target?: { rowIds?: readonly string[] }): void;
  /** Opens the popover for a cell. `false` for a hole, a filtered-out row, or a hidden column. */
  openComments(ref: { rowId: string; columnId: string }): boolean;
  closeComments(): void;
  /** Pass as the context menu's `getCellMenuItems` to add a "Comments…" item. */
  getCommentMenuItems: CommentMenuItemsResolver;
};

import { mergeLabelLayers } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Every string of the comments UI. Functions take the values to insert; the plural form is the function's job. */
export type DataGridCommentsLabels = {
  popover: (columnTitle: string, cellText: string) => string;
  /** Locale of the comment times. Pinned so the server and the client render the same text. */
  locale: string;
  commentList: string;
  composer: string;
  composerPlaceholder: string;
  submit: string;
  cancel: string;
  save: string;
  editAction: string;
  deleteAction: string;
  confirmDeleteAction: string;
  resolveAction: string;
  reopenAction: string;
  edit: (name: string, time: string) => string;
  remove: (name: string, time: string) => string;
  confirmRemove: (name: string, time: string) => string;
  resolve: (name: string, time: string) => string;
  reopen: (name: string, time: string) => string;
  resolved: string;
  saving: string;
  loading: string;
  loadFailed: string;
  retry: string;
  discard: string;
  saveMine: string;
  changedByOther: string;
  readOnlyHint: string;
  noUserHint: string;
  rowBusyHint: string;
  refused: string;
  failed: string;
  counter: (used: number, max: number) => string;
  menuItem: string;
  noComments: string;
  announce: (count: number, unresolved: number, chord: string) => string;
  announceAdded: (name: string) => string;
  unknownAuthor: string;
};

export const DEFAULT_COMMENTS_LABELS: DataGridCommentsLabels = {
  popover: (columnTitle, cellText) => (cellText ? `Comments on ${columnTitle}: ${cellText}` : `Comments on ${columnTitle}`),
  locale: "en-US",
  commentList: "Comments",
  composer: "Write a comment",
  composerPlaceholder: "Write a comment…",
  submit: "Comment",
  cancel: "Cancel",
  save: "Save",
  editAction: "Edit",
  deleteAction: "Delete",
  confirmDeleteAction: "Delete?",
  resolveAction: "Resolve",
  reopenAction: "Reopen",
  edit: (name, time) => `Edit comment by ${name}, ${time}`,
  remove: (name, time) => `Delete comment by ${name}, ${time}`,
  confirmRemove: (name, time) => `Confirm delete of comment by ${name}, ${time}`,
  resolve: (name, time) => `Resolve comment by ${name}, ${time}`,
  reopen: (name, time) => `Reopen comment by ${name}, ${time}`,
  resolved: "Resolved",
  saving: "Saving",
  loading: "Loading comments…",
  loadFailed: "Could not load comments",
  retry: "Retry",
  discard: "Discard",
  saveMine: "Save my version",
  changedByOther: "Changed by someone else",
  readOnlyHint: "Comments are read-only.",
  noUserHint: "Sign in to comment.",
  rowBusyHint: "This row is still saving. Try again in a moment.",
  refused: "You cannot do this.",
  failed: "The comment could not be saved.",
  counter: (used, max) => `${used} / ${max}`,
  menuItem: "Comments…",
  noComments: "No comments yet.",
  announce: (count, unresolved, chord) => `${count} ${count === 1 ? "comment" : "comments"}, ${unresolved} unresolved. Press ${chord} to open.`,
  announceAdded: (name) => `Comment added by ${name}`,
  unknownAuthor: "Unknown",
};

/** The default labels under `overrides`; a key set to `undefined` keeps its default. */
export function resolveCommentsLabels(overrides: Partial<DataGridCommentsLabels> | undefined): DataGridCommentsLabels {
  return mergeLabelLayers<DataGridCommentsLabels>(DEFAULT_COMMENTS_LABELS, overrides);
}

import { toSafeText } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { AckOutcome } from "./comment-state";
import type { CellComment, CommentAuthor, CommentChange } from "./types";

const MAX_ID_LENGTH = 128;
const MAX_NAME_LENGTH = 80;
const MAX_COLOR_LENGTH = 64;
export const MAX_VERSION = 1_000_000_000;

export type Bounds = {
  maxTextLength: number;
  maxCommentsPerCell: number;
  maxComments: number;
  maxCachedRows: number;
};

export const DEFAULT_BOUNDS: Bounds = { maxTextLength: 2000, maxCommentsPerCell: 50, maxComments: 50_000, maxCachedRows: 2000 };
const BOUND_CEILINGS: Bounds = { maxTextLength: 20_000, maxCommentsPerCell: 500, maxComments: 500_000, maxCachedRows: 20_000 };

function bound(value: number | undefined, fallback: number, ceiling: number): number {
  if (value === undefined || !Number.isInteger(value) || value <= 0) return fallback;
  return Math.min(value, ceiling);
}

/** NaN, zero, negative, and fractional values fall back to the default; large values clamp to the ceiling. */
export function resolveBounds(options: Partial<Bounds>): Bounds {
  return {
    maxTextLength: bound(options.maxTextLength, DEFAULT_BOUNDS.maxTextLength, BOUND_CEILINGS.maxTextLength),
    maxCommentsPerCell: bound(options.maxCommentsPerCell, DEFAULT_BOUNDS.maxCommentsPerCell, BOUND_CEILINGS.maxCommentsPerCell),
    maxComments: bound(options.maxComments, DEFAULT_BOUNDS.maxComments, BOUND_CEILINGS.maxComments),
    maxCachedRows: bound(options.maxCachedRows, DEFAULT_BOUNDS.maxCachedRows, BOUND_CEILINGS.maxCachedRows),
  };
}

// eslint-disable-next-line no-control-regex
const CONTROL = /[\u0000-\u001f\u007f-\u009f]/;
// eslint-disable-next-line no-control-regex
const CONTROL_OR_BIDI_G = /[\u0000-\u001f\u007f-\u009f‎‏\u202a-\u202e\u2066-\u2069]/g;

type Raw = {
  id?: unknown; name?: unknown; color?: unknown; rowId?: unknown; columnId?: unknown; text?: unknown; createdAt?: unknown;
  updatedAt?: unknown; version?: unknown; resolved?: unknown; author?: unknown; writeId?: unknown; resolvedBy?: unknown;
  resolvedAt?: unknown; kind?: unknown; baseVersion?: unknown; comment?: unknown;
};

export function isSafeId(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && value.length <= MAX_ID_LENGTH && !CONTROL.test(value);
}

/** Strips control and bidi-override characters and bounds the length. */
export function sanitizeName(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const clean = value.slice(0, MAX_NAME_LENGTH * 2).replace(CONTROL_OR_BIDI_G, "").trim().slice(0, MAX_NAME_LENGTH);
  return clean === "" ? undefined : clean;
}

/** Validates an author into a fresh frozen object, or `null`. */
export function validateAuthor(value: unknown): CommentAuthor | null {
  try {
    return readAuthor(value);
  } catch {
    return null;
  }
}

function readAuthor(value: unknown): CommentAuthor | null {
  if (typeof value !== "object" || value === null) return null;
  const raw = value as Raw;
  const id = raw.id;
  const rawName = raw.name;
  const color = raw.color;
  if (!isSafeId(id)) return null;
  const author: CommentAuthor = { id };
  const name = sanitizeName(rawName);
  if (name !== undefined) author.name = name;
  if (typeof color === "string" && color.length > 0 && color.length <= MAX_COLOR_LENGTH && !CONTROL.test(color)) author.color = color;
  return Object.freeze(author);
}

function isEpoch(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

export function isVersion(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 1 && value <= MAX_VERSION;
}

/** `toSafeText` plus trim: the text a write stores. The caller checks the bounds on the result. */
export function cleanText(value: unknown): string {
  return toSafeText(value).trim();
}

/** Validates one record into a fresh frozen object (each field read once), or `null`. Text over `maxTextLength` is a breach, never truncated. */
export function validateComment(value: unknown, bounds: Bounds): CellComment | null {
  try {
    return readComment(value, bounds);
  } catch {
    return null;
  }
}

function readComment(value: unknown, bounds: Bounds): CellComment | null {
  if (typeof value !== "object" || value === null) return null;
  const raw = value as Raw;
  const id = raw.id;
  const rowId = raw.rowId;
  const columnId = raw.columnId;
  const rawText = raw.text;
  const createdAt = raw.createdAt;
  const updatedAt = raw.updatedAt;
  const version = raw.version;
  const resolved = raw.resolved;
  const rawAuthor = raw.author;
  const writeId = raw.writeId;
  const rawResolvedBy = raw.resolvedBy;
  const resolvedAt = raw.resolvedAt;
  if (!isSafeId(id) || !isSafeId(rowId) || !isSafeId(columnId)) return null;
  if (typeof rawText !== "string" || rawText.length > bounds.maxTextLength * 4) return null;
  const text = rawText.trim();
  if (text.length < 1 || text.length > bounds.maxTextLength) return null;
  if (!isEpoch(createdAt) || !isEpoch(updatedAt) || !isVersion(version) || typeof resolved !== "boolean") return null;
  const author = validateAuthor(rawAuthor);
  if (!author) return null;
  const record: CellComment = { id, rowId, columnId, text, author, createdAt, updatedAt, version, resolved };
  if (writeId !== undefined) {
    if (!isSafeId(writeId)) return null;
    record.writeId = writeId;
  }
  if (rawResolvedBy !== undefined) {
    const resolvedBy = validateAuthor(rawResolvedBy);
    if (!resolvedBy) return null;
    record.resolvedBy = resolvedBy;
  }
  if (resolvedAt !== undefined) {
    if (!isEpoch(resolvedAt)) return null;
    record.resolvedAt = resolvedAt;
  }
  return Object.freeze(record);
}

/** Validates a change (an upsert with a record, or a delete tombstone) into a fresh frozen object, or `null`. */
export function validateChange(value: unknown, bounds: Bounds): CommentChange | null {
  try {
    return readChange(value, bounds);
  } catch {
    return null;
  }
}

function readChange(value: unknown, bounds: Bounds): CommentChange | null {
  if (typeof value !== "object" || value === null) return null;
  const raw = value as Raw;
  const kind = raw.kind;
  const baseVersion = raw.baseVersion;
  if (baseVersion !== undefined && !(typeof baseVersion === "number" && Number.isInteger(baseVersion) && baseVersion >= 0 && baseVersion <= MAX_VERSION)) return null;
  if (kind === "upsert") {
    const comment = validateComment(raw.comment, bounds);
    if (!comment) return null;
    return Object.freeze(baseVersion === undefined ? { kind: "upsert" as const, comment } : { kind: "upsert" as const, comment, baseVersion });
  }
  if (kind === "delete") {
    const id = raw.id;
    const rowId = raw.rowId;
    const columnId = raw.columnId;
    const version = raw.version;
    const writeId = raw.writeId;
    if (!isSafeId(id) || !isSafeId(rowId) || !isSafeId(columnId) || !isVersion(version)) return null;
    if (writeId !== undefined && !isSafeId(writeId)) return null;
    const change: CommentChange = { kind: "delete", id, rowId, columnId, version };
    if (writeId !== undefined) change.writeId = writeId;
    if (baseVersion !== undefined) change.baseVersion = baseVersion;
    return Object.freeze(change);
  }
  return null;
}

/** Reads an `onCommentSave` answer: unknown shapes accept the write as sent, records pass `validateComment`. */
export function parseSaveAnswer(raw: unknown, bounds: Bounds): AckOutcome {
  if (raw === undefined || raw === null) return { kind: "void", server: true };
  if (typeof raw !== "object") return { kind: "void", server: true };
  const record = raw as { comment?: unknown; rejected?: { reason?: unknown; message?: unknown; current?: unknown } };
  if (record.rejected && typeof record.rejected === "object") {
    const { reason, message, current } = record.rejected;
    const allowed = reason === "stale" || reason === "forbidden" || reason === "invalid" || reason === "limit";
    const out: Extract<AckOutcome, { kind: "rejected" }> = { kind: "rejected", reason: allowed ? reason : "invalid" };
    if (typeof message === "string") out.message = message.slice(0, 200);
    if (current === null) out.current = null;
    else if (current !== undefined) {
      const valid = validateComment(current, bounds);
      if (valid) out.current = valid;
    }
    return out;
  }
  if ("comment" in record) {
    if (record.comment === null) return { kind: "record", comment: null };
    if (record.comment === undefined) return { kind: "void", server: true };
    const valid = validateComment(record.comment, bounds);
    return valid ? { kind: "record", comment: valid } : { kind: "invalid" };
  }
  return { kind: "void", server: true };
}

function randomHex(bytes: number): string {
  const values = new Uint8Array(bytes);
  if (typeof crypto !== "undefined" && typeof crypto.getRandomValues === "function") crypto.getRandomValues(values);
  else for (let i = 0; i < bytes; i += 1) values[i] = Math.floor(Math.random() * 256);
  return Array.from(values, (v) => v.toString(16).padStart(2, "0")).join("");
}

/** `crypto.randomUUID` where it exists, a `getRandomValues` fallback on plain-http hosts. */
export function defaultCreateId(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") return crypto.randomUUID();
  return randomHex(16);
}

/** A write id generator: a random prefix per instance (drawn on the first write, never during render) plus a random suffix, so a peer cannot predict or forge an echo. */
export function createWriteIdGenerator(): () => string {
  let prefix: string | undefined;
  return () => {
    prefix ??= randomHex(6);
    return `${prefix}-${randomHex(8)}`;
  };
}

import type {
  ApplyRemoteSkipReason,
  ApplyRemoteVerdict,
  CellComment,
  CommentAction,
  CommentChange,
  CommentRejectedCtx,
  CommentRejectReason,
  CommentSaveRejectReason,
  CommentSource,
} from "./types";
import type { Bounds } from "./validate";

export const TOMBSTONE_TTL_MS = 10 * 60_000;
export const MAX_TOMBSTONES = 10_000;
export const MAX_REMOTE_BATCH = 10_000;
export const MAX_ALIASES = 10_000;
export const MAX_DRAFTS = 50;
export const MAX_FETCH_LOG = 1000;
export const OWN_WRITE_GRACE_MS = 30_000;
export const EMITTED_MEMORY_MS = 30_000;
export const MAX_EMITTED = 10_000;
export const MAX_LISTED_SKIPS = 100;

export type Pending = {
  writeId: string;
  action: CommentAction;
  baseVersion: number;
  baseWriteId: string | undefined;
  change: CommentChange;
  /** The optimistic record shown while saving; the confirmed record for a delete. */
  record: CellComment;
  superseded: boolean;
};

export type Conflict = {
  id: string;
  rowId: string;
  columnId: string;
  action: CommentAction;
  reason: CommentRejectReason;
  message?: string;
  writeId: string;
  baseVersion: number;
  baseWriteId: string | undefined;
  change: CommentChange;
  record: CellComment;
  /** The write's outcome is unknown: an echo of `writeId` still confirms it. */
  thrown: boolean;
  /** The text the user had submitted. */
  text?: string;
  /** Version of the record the conflict UI shows; "Save my version" writes on top of it. */
  shownVersion: number;
  /** A stale answer without `current`: nothing but Discard is offered. */
  discardOnly: boolean;
};

export type Draft = {
  key: string;
  kind: "new" | "edit";
  commentId?: string;
  rowId: string;
  columnId: string;
  text: string;
  baseVersion: number;
  baseWriteId: string | undefined;
};

export type Tombstone = { id: string; rowId: string; columnId: string; version: number; expiresAt: number };

export type FetchRequest = { rowIds: Set<string>; startSeq: number; overflow: boolean; remapped: boolean; log: number };

export type CommentsState = {
  bounds: Bounds;
  controlled: boolean;
  confirmed: Map<string, CellComment>;
  serverConfirmed: Map<string, number>;
  tombstones: Map<string, Tombstone>;
  pending: Map<string, Pending>;
  conflicts: Map<string, Conflict>;
  drafts: Map<string, Draft>;
  index: Map<string, Map<string, Set<string>>>;
  touched: Map<string, number>;
  ownConfirmedAt: Map<string, number>;
  seq: number;
  aliases: Map<string, string>;
  requests: Map<number, FetchRequest>;
  rowRequest: Map<string, number>;
  fetchedRows: Set<string>;
  propRaw: Map<string, CellComment>;
  rawOf: Map<string, { valid: CellComment; raw: CellComment }>;
  emitted: Map<string, number>;
  /** Count of prop or seed records dropped by validation or a bound, for the development warning. */
  dropped: number;
};

export type Emit =
  | { t: "change"; changes: CommentChange[]; source: CommentSource }
  | { t: "local"; change: CommentChange }
  | { t: "rejected"; ctx: CommentRejectedCtx }
  | { t: "refetch"; rowIds: string[] }
  | { t: "warn"; message: string };

export type AckOutcome =
  | { kind: "void"; server: boolean }
  | { kind: "record"; comment: CellComment | null }
  | { kind: "rejected"; reason: CommentSaveRejectReason; message?: string; current?: CellComment | null }
  | { kind: "throw"; error: unknown }
  | { kind: "invalid" };

export type CommentEvent =
  | { type: "localWrite"; action: CommentAction; change: CommentChange; record: CellComment; baseWriteId: string | undefined; now: number }
  | { type: "ack"; id: string; writeId: string; outcome: AckOutcome; now: number }
  | { type: "remote"; changes: readonly { index: number; change: CommentChange }[]; invalid: readonly number[]; truncated: number; now: number }
  | { type: "fetchStart"; requestId: number; rowIds: readonly string[] }
  | { type: "fetchAnswer"; requestId: number; records: readonly CellComment[]; rawIds: ReadonlySet<string>; now: number }
  | { type: "fetchFail"; requestId: number }
  | { type: "propChange"; next: readonly CellComment[]; now: number }
  | { type: "remove"; rowIds: readonly string[]; now: number }
  | { type: "evict"; rowIds: readonly string[]; keepRows: ReadonlySet<string> }
  | { type: "idSwap"; map: ReadonlyMap<string, string> }
  | { type: "invalidateRows"; rowIds: readonly string[] | null }
  | { type: "expire"; now: number };

export type ReduceResult = { emits: Emit[]; verdict?: ApplyRemoteVerdict; ok?: boolean; removed?: number; limited?: number };

export type Ctx = { st: CommentsState; out: Emit[]; changes: CommentChange[]; now: number };
export type Skip = ApplyRemoteSkipReason;

export function createCommentsState(bounds: Bounds, controlled: boolean): CommentsState {
  return {
    bounds,
    controlled,
    confirmed: new Map(),
    serverConfirmed: new Map(),
    tombstones: new Map(),
    pending: new Map(),
    conflicts: new Map(),
    drafts: new Map(),
    index: new Map(),
    touched: new Map(),
    ownConfirmedAt: new Map(),
    seq: 0,
    aliases: new Map(),
    requests: new Map(),
    rowRequest: new Map(),
    fetchedRows: new Set(),
    propRaw: new Map(),
    rawOf: new Map(),
    emitted: new Map(),
    dropped: 0,
  };
}

export const newDraftKey = (rowId: string, columnId: string): string => `n\u0001${rowId}\u0001${columnId}`;
export const editDraftKey = (id: string): string => `e\u0001${id}`;

export function sameAuthor(a: CellComment["author"] | undefined, b: CellComment["author"] | undefined): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  return a.id === b.id && a.name === b.name && a.color === b.color;
}

/** Equality over every typed field of a record. */
export function sameRecord(a: CellComment, b: CellComment): boolean {
  return (
    a === b ||
    (a.id === b.id &&
      a.rowId === b.rowId &&
      a.columnId === b.columnId &&
      a.text === b.text &&
      a.version === b.version &&
      a.writeId === b.writeId &&
      a.createdAt === b.createdAt &&
      a.updatedAt === b.updatedAt &&
      a.resolved === b.resolved &&
      a.resolvedAt === b.resolvedAt &&
      sameAuthor(a.author, b.author) &&
      sameAuthor(a.resolvedBy, b.resolvedBy))
  );
}

/** Orders the comments of one cell: `(createdAt, id)` ascending. */
export function compareComments(a: CellComment, b: CellComment): number {
  return a.createdAt - b.createdAt || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
}

/** The record the UI shows for an id: the optimistic record of a live pending write, else the confirmed record. */
export function displayRecord(st: CommentsState, id: string): CellComment | undefined {
  const p = st.pending.get(id);
  if (p && !p.superseded) return p.record;
  return st.confirmed.get(id);
}

/** The comments of one cell in display order, with their saving flag. */
export function cellComments(st: CommentsState, rowId: string, columnId: string): { comment: CellComment; saving: boolean }[] {
  const ids = st.index.get(rowId)?.get(columnId);
  if (!ids) return [];
  const list: { comment: CellComment; saving: boolean }[] = [];
  for (const id of ids) {
    const comment = displayRecord(st, id);
    if (comment) list.push({ comment, saving: st.pending.get(id)?.superseded === false });
  }
  return list.sort((x, y) => compareComments(x.comment, y.comment));
}

export function bump(c: Ctx, id: string): void {
  if (c.st.touched.size > 50_000 && c.st.requests.size === 0) c.st.touched.clear();
  c.st.seq += 1;
  c.st.touched.set(id, c.st.seq);
}

export function indexAdd(st: CommentsState, id: string, rowId: string, columnId: string): void {
  let columns = st.index.get(rowId);
  if (!columns) st.index.set(rowId, (columns = new Map<string, Set<string>>()));
  let ids = columns.get(columnId);
  if (!ids) columns.set(columnId, (ids = new Set<string>()));
  ids.add(id);
}

export function indexRemove(st: CommentsState, id: string, rowId: string, columnId: string): void {
  const columns = st.index.get(rowId);
  const ids = columns?.get(columnId);
  if (!columns || !ids) return;
  ids.delete(id);
  if (ids.size === 0) columns.delete(columnId);
  if (columns.size === 0) st.index.delete(rowId);
}

export function syncIndex(st: CommentsState, id: string, rowId: string, columnId: string): void {
  if (st.confirmed.has(id) || st.pending.has(id)) indexAdd(st, id, rowId, columnId);
  else indexRemove(st, id, rowId, columnId);
}

export function resolveAlias(st: CommentsState, rowId: string): string {
  let current = rowId;
  for (let hop = 0; hop < 5; hop += 1) {
    const next = st.aliases.get(current);
    if (next === undefined) break;
    current = next;
  }
  return current;
}

export function withAlias(st: CommentsState, rec: CellComment): CellComment {
  const rowId = resolveAlias(st, rec.rowId);
  return rowId === rec.rowId ? rec : Object.freeze({ ...rec, rowId });
}

export function changeAlias(st: CommentsState, change: CommentChange): CommentChange {
  if (change.kind === "upsert") {
    const comment = withAlias(st, change.comment);
    return comment === change.comment ? change : Object.freeze({ ...change, comment });
  }
  const rowId = resolveAlias(st, change.rowId);
  return rowId === change.rowId ? change : Object.freeze({ ...change, rowId });
}

export function addrOf(st: CommentsState, id: string): { rowId: string; columnId: string } | undefined {
  const c = st.confirmed.get(id);
  if (c) return c;
  const t = st.tombstones.get(id);
  if (t) return t;
  const p = st.pending.get(id);
  return p?.record;
}

export function cellCount(st: CommentsState, rowId: string, columnId: string): number {
  return st.index.get(rowId)?.get(columnId)?.size ?? 0;
}

export function noteRowActivity(st: CommentsState, rowId: string): void {
  const requestId = st.rowRequest.get(rowId);
  if (requestId === undefined) return;
  const req = st.requests.get(requestId);
  if (!req) return;
  req.log += 1;
  if (req.log > MAX_FETCH_LOG) req.overflow = true;
}

export function addTombstone(c: Ctx, id: string, rowId: string, columnId: string, version: number): void {
  const { st } = c;
  const prior = st.tombstones.get(id);
  st.tombstones.delete(id);
  st.tombstones.set(id, { id, rowId, columnId, version: Math.max(version, prior?.version ?? 0), expiresAt: c.now + TOMBSTONE_TTL_MS });
  while (st.tombstones.size > MAX_TOMBSTONES) {
    const oldest = st.tombstones.keys().next().value;
    if (oldest === undefined) break;
    st.tombstones.delete(oldest);
  }
}

export function markEmitted(c: Ctx, id: string): void {
  if (!c.st.controlled) return;
  c.st.emitted.delete(id);
  c.st.emitted.set(id, c.now);
  while (c.st.emitted.size > MAX_EMITTED) {
    const oldest = c.st.emitted.keys().next().value;
    if (oldest === undefined) break;
    c.st.emitted.delete(oldest);
  }
}

export function setConfirmed(c: Ctx, rec: CellComment, server: boolean, silent = false): void {
  const { st } = c;
  const prev = st.confirmed.get(rec.id);
  if (prev && (prev.rowId !== rec.rowId || prev.columnId !== rec.columnId)) indexRemove(st, rec.id, prev.rowId, prev.columnId);
  st.confirmed.set(rec.id, rec);
  st.ownConfirmedAt.delete(rec.id);
  if (server) st.serverConfirmed.set(rec.id, rec.version);
  else st.serverConfirmed.delete(rec.id);
  const tomb = st.tombstones.get(rec.id);
  if (tomb && rec.version > tomb.version) st.tombstones.delete(rec.id);
  syncIndex(st, rec.id, rec.rowId, rec.columnId);
  bump(c, rec.id);
  noteRowActivity(st, rec.rowId);
  if (!silent) {
    c.changes.push({ kind: "upsert", comment: rec });
    markEmitted(c, rec.id);
  }
}

export function removeConfirmed(c: Ctx, id: string, version: number, writeId: string | undefined, opts: { tombstone: boolean; silent?: boolean }): void {
  const { st } = c;
  const prev = st.confirmed.get(id);
  if (!prev) return;
  st.confirmed.delete(id);
  st.serverConfirmed.delete(id);
  st.rawOf.delete(id);
  syncIndex(st, id, prev.rowId, prev.columnId);
  bump(c, id);
  noteRowActivity(st, prev.rowId);
  if (opts.tombstone) addTombstone(c, id, prev.rowId, prev.columnId, version);
  if (!opts.silent) {
    const change: CommentChange = { kind: "delete", id, rowId: prev.rowId, columnId: prev.columnId, version };
    if (writeId !== undefined) change.writeId = writeId;
    c.changes.push(change);
    markEmitted(c, id);
  }
}

/** Sets or replaces a draft (the composer, an edit). The least recently edited of more than 50 drafts is dropped. */
export function putDraft(st: CommentsState, draft: Draft): void {
  st.drafts.delete(draft.key);
  st.drafts.set(draft.key, draft);
  while (st.drafts.size > MAX_DRAFTS) {
    const oldest = st.drafts.keys().next().value;
    if (oldest === undefined) break;
    st.drafts.delete(oldest);
  }
}

export function discardDraft(st: CommentsState, key: string): void {
  st.drafts.delete(key);
}

export function setConflict(st: CommentsState, conflict: Conflict): void {
  st.conflicts.delete(conflict.id);
  st.conflicts.set(conflict.id, conflict);
  while (st.conflicts.size > MAX_DRAFTS) {
    const oldest = st.conflicts.keys().next().value;
    if (oldest === undefined) break;
    st.conflicts.delete(oldest);
  }
}

export function discardConflict(st: CommentsState, id: string): void {
  st.conflicts.delete(id);
}

/** Moves the text of an open edit draft or conflict to the new-comment draft of the cell, so a deleted comment never takes typed text with it. */
export function keepDraftText(st: CommentsState, id: string, rowId: string, columnId: string): void {
  const text = st.drafts.get(editDraftKey(id))?.text ?? st.conflicts.get(id)?.text;
  const key = newDraftKey(rowId, columnId);
  if (text && !st.drafts.has(key)) putDraft(st, { key, kind: "new", rowId, columnId, text, baseVersion: 0, baseWriteId: undefined });
}

export function dropCommentUi(st: CommentsState, id: string): void {
  st.conflicts.delete(id);
  st.drafts.delete(editDraftKey(id));
}

export function rebaseDraft(st: CommentsState, p: Pending, confirmed: CellComment): void {
  const draft = st.drafts.get(editDraftKey(p.change.kind === "upsert" ? p.change.comment.id : (p.change as { id: string }).id));
  if (draft && draft.baseVersion === p.baseVersion && draft.baseWriteId === p.baseWriteId && confirmed.version === p.baseVersion + 1) {
    draft.baseVersion = confirmed.version;
    draft.baseWriteId = confirmed.writeId;
  }
}

/** The confirmed records; a record the add-on never changed keeps the app object it came from. */
export function confirmedSnapshot(st: CommentsState): CellComment[] {
  const list: CellComment[] = [];
  for (const [id, record] of st.confirmed) {
    const origin = st.rawOf.get(id);
    list.push(origin && origin.valid === record ? origin.raw : record);
  }
  return list;
}

import type { ApplyRemoteVerdict, CellComment, CommentChange, CommentRejectedCtx, CommentRejectReason, CommentSource } from "./types";
import { validateComment } from "./validate";
import {
  addrOf,
  addTombstone,
  bump,
  cellCount,
  changeAlias,
  dropCommentUi,
  editDraftKey,
  EMITTED_MEMORY_MS,
  indexAdd,
  indexRemove,
  keepDraftText,
  MAX_ALIASES,
  MAX_LISTED_SKIPS,
  newDraftKey,
  OWN_WRITE_GRACE_MS,
  putDraft,
  rebaseDraft,
  removeConfirmed,
  sameRecord,
  setConfirmed,
  setConflict,
  syncIndex,
  withAlias,
  type AckOutcome,
  type CommentEvent,
  type CommentsState,
  type Conflict,
  type Ctx,
  type Emit,
  type Pending,
  type ReduceResult,
  type Skip,
} from "./comment-state";

function pushLocal(c: Ctx, change: CommentChange): void {
  c.out.push({ t: "local", change });
}

function authoritativeChange(rec: CellComment, p: Pending): CommentChange {
  return { kind: "upsert", comment: rec, baseVersion: p.baseVersion };
}

/** Rule 4(a)/(6): a write is confirmed by `rec`. */
function confirmPendingUpsert(c: Ctx, p: Pending, rec: CellComment, server: boolean, silent: boolean): void {
  const { st } = c;
  st.pending.delete(rec.id);
  setConfirmed(c, rec, server, silent);
  st.ownConfirmedAt.set(rec.id, c.now);
  const conflict = st.conflicts.get(rec.id);
  if (conflict && (conflict.writeId === p.writeId || conflict.thrown)) st.conflicts.delete(rec.id);
  rebaseDraft(st, p, rec);
  pushLocal(c, authoritativeChange(rec, p));
}

function confirmPendingDelete(c: Ctx, p: Pending, version: number, silent: boolean): void {
  const { st } = c;
  const id = p.record.id;
  st.pending.delete(id);
  removeConfirmed(c, id, version, p.writeId, { tombstone: true, silent });
  if (!st.confirmed.has(id)) addTombstone(c, id, p.record.rowId, p.record.columnId, version);
  st.conflicts.delete(id);
  st.drafts.delete(editDraftKey(id));
  syncIndex(st, id, p.record.rowId, p.record.columnId);
  pushLocal(c, { kind: "delete", id, rowId: p.record.rowId, columnId: p.record.columnId, version, writeId: p.writeId, baseVersion: p.baseVersion });
}

/** The thrown write whose echo still confirms it. */
function thrownEcho(st: CommentsState, id: string, writeId: string | undefined, version: number): Conflict | undefined {
  const conflict = st.conflicts.get(id);
  if (!conflict || !conflict.thrown || writeId === undefined || conflict.writeId !== writeId) return undefined;
  return version >= conflict.baseVersion + 1 ? conflict : undefined;
}

function conflictAsPending(conflict: Conflict): Pending {
  return {
    writeId: conflict.writeId,
    action: conflict.action,
    baseVersion: conflict.baseVersion,
    baseWriteId: conflict.baseWriteId,
    change: conflict.change,
    record: conflict.record,
    superseded: false,
  };
}

function tieWins(st: CommentsState, current: CellComment, incoming: CellComment, incomingServer: boolean, fetchUntouched: boolean): boolean {
  if (fetchUntouched) return true;
  const currentServer = st.serverConfirmed.get(current.id) === current.version;
  if (incomingServer && !currentServer) return true;
  if (!incomingServer && currentServer) return false;
  if (incoming.updatedAt !== current.updatedAt) return incoming.updatedAt > current.updatedAt;
  return (incoming.writeId ?? "") > (current.writeId ?? "");
}

type UpsertOpts = { server: boolean; fetchUntouched?: boolean };

/** Rules 3 to 5 for one incoming upsert of a known or unknown id. */
function applyUpsert(c: Ctx, raw: CellComment, opts: UpsertOpts): "applied" | Skip {
  const { st } = c;
  const rec = withAlias(st, raw);
  const id = rec.id;
  const known = addrOf(st, id);
  if (known && (known.rowId !== rec.rowId || known.columnId !== rec.columnId)) return "invalid";
  const confirmed = st.confirmed.get(id);
  if (confirmed && confirmed.author.id !== rec.author.id) return "invalid";
  const p = st.pending.get(id);
  if (p && !p.superseded && p.action !== "delete" && rec.writeId !== undefined && rec.writeId === p.writeId && rec.version >= p.baseVersion + 1) {
    confirmPendingUpsert(c, p, rec, opts.server, false);
    return "applied";
  }
  const thrown = thrownEcho(st, id, rec.writeId, rec.version);
  if (thrown && thrown.action !== "delete") {
    confirmPendingUpsert(c, conflictAsPending(thrown), rec, opts.server, false);
    return "applied";
  }
  const tomb = st.tombstones.get(id);
  if (tomb) {
    const resurrect = rec.version === tomb.version && opts.fetchUntouched === true;
    if (rec.version < tomb.version || (rec.version === tomb.version && !resurrect)) return "tombstoned";
  }
  if (confirmed) {
    if (rec.version < confirmed.version) return "stale";
    if (rec.version === confirmed.version) {
      if (rec.writeId !== undefined && rec.writeId === confirmed.writeId) return "duplicate";
      if (!tieWins(st, confirmed, rec, opts.server, opts.fetchUntouched === true)) return "stale";
    }
  } else if (!tomb || rec.version > tomb.version || opts.fetchUntouched) {
    if (st.confirmed.size + st.pending.size >= st.bounds.maxComments) return "limit";
    if (cellCount(st, rec.rowId, rec.columnId) >= st.bounds.maxCommentsPerCell) return "limit";
  }
  setConfirmed(c, rec, opts.server);
  return "applied";
}

/** Marks the pending write superseded and offers its text as a draft for a new comment. */
function supersedePending(c: Ctx, p: Pending): void {
  const { st } = c;
  p.superseded = true;
  if ((p.action === "update" || p.action === "create") && p.record.text) {
    const key = newDraftKey(p.record.rowId, p.record.columnId);
    if (!st.drafts.has(key)) putDraft(st, { key, kind: "new", rowId: p.record.rowId, columnId: p.record.columnId, text: p.record.text, baseVersion: 0, baseWriteId: undefined });
  }
}

function applyDelete(c: Ctx, change: Extract<CommentChange, { kind: "delete" }>, opts: UpsertOpts): "applied" | Skip {
  const { st } = c;
  const d = changeAlias(st, change) as Extract<CommentChange, { kind: "delete" }>;
  const id = d.id;
  const known = addrOf(st, id);
  if (known && (known.rowId !== d.rowId || known.columnId !== d.columnId)) return "invalid";
  const p = st.pending.get(id);
  if (p && !p.superseded && p.action === "delete" && d.writeId !== undefined && d.writeId === p.writeId && d.version >= p.baseVersion + 1) {
    confirmPendingDelete(c, p, d.version, false);
    return "applied";
  }
  const thrown = thrownEcho(st, id, d.writeId, d.version);
  if (thrown && thrown.action === "delete") {
    confirmPendingDelete(c, conflictAsPending(thrown), d.version, false);
    return "applied";
  }
  const tomb = st.tombstones.get(id);
  if (tomb && d.version <= tomb.version) return "duplicate";
  const confirmed = st.confirmed.get(id);
  if (!confirmed) {
    const inFlight = st.rowRequest.has(d.rowId);
    if (!inFlight && !p) return "unknown";
    addTombstone(c, id, d.rowId, d.columnId, d.version);
    if (p && !p.superseded) supersedePending(c, p);
    return "applied";
  }
  if (d.version < confirmed.version) return "stale";
  if (d.version === confirmed.version && d.writeId !== undefined && d.writeId === confirmed.writeId) return "duplicate";
  removeConfirmed(c, id, d.version, d.writeId, { tombstone: true });
  if (p && !p.superseded) supersedePending(c, p);
  keepDraftText(st, id, confirmed.rowId, confirmed.columnId);
  dropCommentUi(st, id);
  if (opts.server) st.ownConfirmedAt.delete(id);
  return "applied";
}

function finish(c: Ctx, source: CommentSource): void {
  if (c.changes.length > 0) c.out.push({ t: "change", changes: c.changes, source });
}

function rollback(c: Ctx, p: Pending, ctx: { reason: CommentRejectReason; message?: string; current?: CellComment | null; error?: unknown; thrown: boolean; discardOnly?: boolean }): void {
  const { st } = c;
  const id = p.record.id;
  st.pending.delete(id);
  syncIndex(st, id, p.record.rowId, p.record.columnId);
  const text = p.action === "create" || p.action === "update" ? p.record.text : undefined;
  const confirmed = st.confirmed.get(id);
  setConflict(st, {
    id,
    rowId: p.record.rowId,
    columnId: p.record.columnId,
    action: p.action,
    reason: ctx.reason,
    message: ctx.message,
    writeId: p.writeId,
    baseVersion: p.baseVersion,
    baseWriteId: p.baseWriteId,
    change: p.change,
    record: p.record,
    thrown: ctx.thrown,
    text,
    shownVersion: confirmed?.version ?? p.baseVersion,
    discardOnly: ctx.discardOnly === true,
  });
  if (text !== undefined) {
    const asNew = p.action === "create" || !st.confirmed.has(id);
    const key = asNew ? newDraftKey(p.record.rowId, p.record.columnId) : editDraftKey(id);
    putDraft(st, { key, kind: asNew ? "new" : "edit", commentId: asNew ? undefined : id, rowId: p.record.rowId, columnId: p.record.columnId, text, baseVersion: asNew ? 0 : p.baseVersion, baseWriteId: asNew ? undefined : p.baseWriteId });
  }
  const rejected: CommentRejectedCtx = { action: p.action, change: p.change, reason: ctx.reason };
  if (ctx.message !== undefined) rejected.message = ctx.message;
  if (ctx.current !== undefined) rejected.current = ctx.current;
  if (ctx.error !== undefined) rejected.error = ctx.error;
  c.out.push({ t: "rejected", ctx: rejected });
}

function handleAck(c: Ctx, id: string, writeId: string, outcome: AckOutcome): void {
  const { st } = c;
  const p = st.pending.get(id);
  if (!p || p.writeId !== writeId) {
    if (outcome.kind === "record" && outcome.comment) applyUpsert(c, outcome.comment, { server: true });
    else if (outcome.kind === "rejected" && outcome.current && outcome.current.writeId === writeId) applyUpsert(c, outcome.current, { server: true });
    return;
  }
  if (p.superseded) {
    st.pending.delete(id);
    syncIndex(st, id, p.record.rowId, p.record.columnId);
    return;
  }
  const confirmed = st.confirmed.get(id);
  const tomb = st.tombstones.get(id);
  const nextVersion = p.baseVersion + 1;
  const supersede = (): void => {
    st.pending.delete(id);
    syncIndex(st, id, p.record.rowId, p.record.columnId);
  };

  if (outcome.kind === "throw") return rollback(c, p, { reason: "error", error: outcome.error, thrown: true });
  if (outcome.kind === "invalid") return rollback(c, p, { reason: "invalid", thrown: false });

  if (outcome.kind === "rejected") {
    const current = outcome.current;
    if (outcome.reason === "stale") {
      if (current && current.writeId === p.writeId) {
        applyUpsert(c, current, { server: true });
        if (st.pending.get(id) === p) confirmPendingUpsert(c, p, withAlias(st, current), true, false);
        return;
      }
      if (current === null && p.action === "delete") return confirmPendingDelete(c, p, Math.max(nextVersion, confirmed?.version ?? 0), false);
      if (current) {
        st.pending.delete(id);
        applyUpsert(c, current, { server: true });
        st.pending.set(id, p);
        rollback(c, p, { reason: "stale", message: outcome.message, current, thrown: false });
        return;
      }
      if (current === null) {
        st.pending.delete(id);
        const known = st.confirmed.get(id);
        if (known) removeConfirmed(c, id, known.version + 1, undefined, { tombstone: true });
        st.pending.set(id, p);
        rollback(c, p, { reason: "stale", message: outcome.message, current: null, thrown: false });
        return;
      }
      c.out.push({ t: "refetch", rowIds: [p.record.rowId] });
      c.out.push({ t: "warn", message: "a stale rejection without `current` leaves Discard only; return `current` from the save, or set `fetchComments`" });
      return rollback(c, p, { reason: "stale", message: outcome.message, thrown: false, discardOnly: true });
    }
    return rollback(c, p, { reason: outcome.reason, message: outcome.message, current: outcome.current, thrown: false });
  }

  const asDelete = p.action === "delete" || (outcome.kind === "record" && outcome.comment === null);
  if (asDelete) {
    if (!confirmed) return supersede();
    if (confirmed.version > nextVersion) return supersede();
    return confirmPendingDelete(c, p, nextVersion, false);
  }

  const server = outcome.kind === "void" ? outcome.server : true;
  if (tomb && !confirmed) return supersede();
  if (outcome.kind === "record" && outcome.comment) {
    const rec = withAlias(st, outcome.comment);
    if (rec.id !== id || rec.rowId !== p.record.rowId || rec.columnId !== p.record.columnId) return rollback(c, p, { reason: "invalid", thrown: false });
    if (confirmed && rec.version < confirmed.version) return supersede();
    if (confirmed && rec.version === confirmed.version && confirmed.writeId !== rec.writeId && !tieWins(st, confirmed, rec, true, false)) return supersede();
    return confirmPendingUpsert(c, p, rec, true, false);
  }
  if (confirmed && confirmed.version > nextVersion) return supersede();
  if (confirmed && confirmed.version === nextVersion && confirmed.writeId !== p.writeId && !tieWins(st, confirmed, p.record, server, false)) return supersede();
  confirmPendingUpsert(c, p, p.record, server, false);
}

function handleLocalWrite(c: Ctx, e: Extract<CommentEvent, { type: "localWrite" }>): boolean {
  const { st } = c;
  const id = e.record.id;
  if (st.pending.has(id)) return false;
  if (e.action === "create") {
    if (st.confirmed.has(id) || st.tombstones.has(id)) return false;
    if (st.confirmed.size + st.pending.size >= st.bounds.maxComments) return false;
    if (cellCount(st, e.record.rowId, e.record.columnId) >= st.bounds.maxCommentsPerCell) return false;
  } else if (!st.confirmed.has(id)) {
    return false;
  }
  st.pending.set(id, {
    writeId: e.change.kind === "upsert" ? (e.change.comment.writeId as string) : (e.change.writeId as string),
    action: e.action,
    baseVersion: e.change.baseVersion ?? 0,
    baseWriteId: e.baseWriteId,
    change: e.change,
    record: e.record,
    superseded: false,
  });
  const conflict = st.conflicts.get(id);
  if (conflict) st.conflicts.delete(id);
  syncIndex(st, id, e.record.rowId, e.record.columnId);
  bump(c, id);
  return true;
}

function handleRemote(c: Ctx, e: Extract<CommentEvent, { type: "remote" }>): ApplyRemoteVerdict {
  const skipped: { index: number; reason: Skip }[] = [];
  let skippedCount = 0;
  let applied = 0;
  const note = (index: number, reason: Skip): void => {
    skippedCount += 1;
    if (skipped.length < MAX_LISTED_SKIPS) skipped.push({ index, reason });
  };
  for (const index of e.invalid) note(index, "invalid");
  for (const { index, change } of e.changes) {
    const result = change.kind === "upsert" ? applyUpsert(c, change.comment, { server: false }) : applyDelete(c, change, { server: false });
    if (result === "applied") applied += 1;
    else note(index, result);
  }
  skipped.sort((a, b) => a.index - b.index);
  return { applied, skippedCount, skipped, truncated: e.truncated };
}

function handleFetchAnswer(c: Ctx, e: Extract<CommentEvent, { type: "fetchAnswer" }>): number {
  const { st } = c;
  const req = st.requests.get(e.requestId);
  if (!req) return 0;
  st.requests.delete(e.requestId);
  for (const row of req.rowIds) if (st.rowRequest.get(row) === e.requestId) st.rowRequest.delete(row);
  if (req.overflow || req.remapped) {
    c.out.push({ t: "refetch", rowIds: Array.from(req.rowIds) });
    return 0;
  }
  let limited = 0;
  for (const record of e.records) {
    if (!req.rowIds.has(record.rowId)) continue;
    const untouched = (st.touched.get(record.id) ?? 0) <= req.startSeq;
    if (applyUpsert(c, record, { server: true, fetchUntouched: untouched }) === "limit") limited += 1;
  }
  for (const row of req.rowIds) {
    const columns = st.index.get(row);
    if (columns) {
      for (const ids of Array.from(columns.values())) {
        for (const id of Array.from(ids)) {
          const rec = st.confirmed.get(id);
          if (!rec || e.rawIds.has(id)) continue;
          if ((st.touched.get(id) ?? 0) > req.startSeq) continue;
          if (st.pending.has(id) || st.conflicts.has(id) || st.drafts.has(editDraftKey(id))) continue;
          const own = st.ownConfirmedAt.get(id);
          if (own !== undefined && c.now - own < OWN_WRITE_GRACE_MS) continue;
          removeConfirmed(c, id, rec.version, undefined, { tombstone: false });
        }
      }
    }
    st.fetchedRows.add(row);
  }
  const cap = Math.max(st.bounds.maxCachedRows * 4, 4000);
  while (st.fetchedRows.size > cap) {
    const oldest = st.fetchedRows.values().next().value;
    if (oldest === undefined) break;
    st.fetchedRows.delete(oldest);
  }
  return limited;
}

function forgetSilently(c: Ctx, id: string): void {
  const { st } = c;
  const rec = st.confirmed.get(id);
  if (!rec) return;
  removeConfirmed(c, id, rec.version, undefined, { tombstone: false, silent: true });
  st.fetchedRows.delete(rec.rowId);
}

function processPropRecord(c: Ctx, raw: CellComment): void {
  const { st } = c;
  const valid = validateComment(raw, st.bounds);
  if (!valid) {
    st.dropped += 1;
    return;
  }
  const rec = withAlias(st, valid);
  st.emitted.delete(rec.id);
  const p = st.pending.get(rec.id);
  if (p && !p.superseded && p.action !== "delete" && rec.writeId !== undefined && rec.writeId === p.writeId && rec.version >= p.baseVersion + 1) {
    confirmPendingUpsert(c, p, rec, true, true);
    st.rawOf.set(rec.id, { valid: rec, raw });
    return;
  }
  const confirmed = st.confirmed.get(rec.id);
  if (confirmed && sameRecord(confirmed, rec)) {
    st.rawOf.set(rec.id, { valid: confirmed, raw });
    return;
  }
  if (!confirmed && st.confirmed.size + st.pending.size >= st.bounds.maxComments) {
    st.dropped += 1;
    return;
  }
  if (!confirmed && cellCount(st, rec.rowId, rec.columnId) >= st.bounds.maxCommentsPerCell) {
    st.dropped += 1;
    return;
  }
  setConfirmed(c, rec, true, true);
  st.rawOf.set(rec.id, { valid: rec, raw });
}

function handlePropChange(c: Ctx, next: readonly CellComment[]): void {
  const { st } = c;
  const nextMap = new Map<string, CellComment>();
  for (const record of next) {
    if (typeof record !== "object" || record === null) {
      st.dropped += 1;
      continue;
    }
    let id: unknown;
    try {
      id = (record as { id?: unknown }).id;
    } catch {
      st.dropped += 1;
      continue;
    }
    if (typeof id === "string" && !nextMap.has(id)) nextMap.set(id, record);
  }
  const previous = st.propRaw;
  st.propRaw = nextMap;
  for (const [id, record] of nextMap) {
    const before = previous.get(id);
    if (before === record) continue;
    if (before && typeof before === "object" && sameRecord(before, record)) continue;
    processPropRecord(c, record);
  }
  for (const id of previous.keys()) {
    if (nextMap.has(id)) continue;
    st.emitted.delete(id);
    st.rawOf.delete(id);
    forgetSilently(c, id);
  }
}

function reconcileEmitted(c: Ctx): void {
  const { st } = c;
  for (const [id, at] of Array.from(st.emitted)) {
    if (c.now - at < EMITTED_MEMORY_MS) continue;
    st.emitted.delete(id);
    const fromProp = st.propRaw.get(id);
    if (!fromProp) {
      forgetSilently(c, id);
      continue;
    }
    const current = st.confirmed.get(id);
    if (!current || !sameRecord(current, fromProp)) processPropRecord(c, fromProp);
  }
}

function handleRemove(c: Ctx, rowIds: readonly string[]): number {
  const { st } = c;
  let removed = 0;
  for (const row of rowIds) {
    st.fetchedRows.delete(row);
    const columns = st.index.get(row);
    if (!columns) continue;
    const ids = Array.from(columns.values()).flatMap((set) => Array.from(set));
    for (const id of ids) {
      const confirmed = st.confirmed.get(id);
      const p = st.pending.get(id);
      const known = confirmed ?? p?.record;
      if (!known) continue;
      const version = Math.max(confirmed?.version ?? 0, (p?.baseVersion ?? 0) + 1);
      st.pending.delete(id);
      if (confirmed) removeConfirmed(c, id, version, undefined, { tombstone: true });
      else {
        addTombstone(c, id, known.rowId, known.columnId, version);
        syncIndex(st, id, known.rowId, known.columnId);
        c.changes.push({ kind: "delete", id, rowId: known.rowId, columnId: known.columnId, version });
        bump(c, id);
      }
      dropCommentUi(st, id);
      st.drafts.delete(newDraftKey(known.rowId, known.columnId));
      removed += 1;
    }
  }
  return removed;
}

function handleEvict(c: Ctx, e: Extract<CommentEvent, { type: "evict" }>): void {
  const { st } = c;
  for (const row of e.rowIds) {
    if (e.keepRows.has(row)) continue;
    const columns = st.index.get(row);
    let blocked = false;
    if (columns) {
      for (const ids of columns.values()) {
        for (const id of ids) {
          if (st.pending.has(id) || st.conflicts.has(id) || st.drafts.has(editDraftKey(id))) blocked = true;
        }
        for (const column of columns.keys()) if (st.drafts.has(newDraftKey(row, column))) blocked = true;
      }
    }
    if (blocked) continue;
    if (columns) {
      for (const id of Array.from(columns.values()).flatMap((set) => Array.from(set))) {
        const rec = st.confirmed.get(id);
        if (rec) removeConfirmed(c, id, rec.version, undefined, { tombstone: false, silent: true });
      }
    }
    st.fetchedRows.delete(row);
  }
}

function handleIdSwap(c: Ctx, map: ReadonlyMap<string, string>): void {
  const { st } = c;
  for (const [oldId, newId] of map) {
    if (oldId === newId) continue;
    st.aliases.set(oldId, newId);
    while (st.aliases.size > MAX_ALIASES) {
      const oldest = st.aliases.keys().next().value;
      if (oldest === undefined) break;
      st.aliases.delete(oldest);
    }
    const columns = st.index.get(oldId);
    const ids = columns ? Array.from(columns.values()).flatMap((set) => Array.from(set)) : [];
    for (const id of ids) {
      const confirmed = st.confirmed.get(id);
      if (confirmed) {
        const moved = Object.freeze({ ...confirmed, rowId: newId });
        indexRemove(st, id, oldId, confirmed.columnId);
        st.confirmed.set(id, moved);
        indexAdd(st, id, newId, moved.columnId);
        st.rawOf.delete(id);
        c.changes.push({ kind: "upsert", comment: moved });
        bump(c, id);
      }
      const p = st.pending.get(id);
      if (p) {
        const record = Object.freeze({ ...p.record, rowId: newId });
        const change: CommentChange = p.change.kind === "upsert" ? { ...p.change, comment: record } : { ...p.change, rowId: newId };
        st.pending.set(id, { ...p, record, change });
        if (!confirmed) {
          indexRemove(st, id, oldId, p.record.columnId);
          indexAdd(st, id, newId, record.columnId);
        }
      }
      const conflict = st.conflicts.get(id);
      if (conflict) st.conflicts.set(id, { ...conflict, rowId: newId });
      const draft = st.drafts.get(editDraftKey(id));
      if (draft) draft.rowId = newId;
    }
    if (columns) {
      for (const column of columns.keys()) {
        const key = newDraftKey(oldId, column);
        const draft = st.drafts.get(key);
        if (draft) {
          st.drafts.delete(key);
          putDraft(st, { ...draft, key: newDraftKey(newId, column), rowId: newId });
        }
      }
    }
    for (const [id, tomb] of st.tombstones) if (tomb.rowId === oldId) st.tombstones.set(id, { ...tomb, rowId: newId });
    if (st.fetchedRows.delete(oldId)) st.fetchedRows.add(newId);
    const requestId = st.rowRequest.get(oldId);
    if (requestId !== undefined) {
      const req = st.requests.get(requestId);
      if (req) req.remapped = true;
    }
  }
}

/** Applies one event to the state. The reducer mutates `st` in place (copying 100k records per event would break the cost budget) and is deterministic: time and ids arrive in the event. */
export function reduce(st: CommentsState, event: CommentEvent): ReduceResult {
  const out: Emit[] = [];
  const c: Ctx = { st, out, changes: [], now: "now" in event ? event.now : 0 };
  switch (event.type) {
    case "localWrite": {
      const ok = handleLocalWrite(c, event);
      return { emits: out, ok };
    }
    case "ack":
      handleAck(c, event.id, event.writeId, event.outcome);
      finish(c, "ack");
      return { emits: out };
    case "remote": {
      const verdict = handleRemote(c, event);
      finish(c, "remote");
      return { emits: out, verdict };
    }
    case "fetchStart": {
      const rowIds = new Set(event.rowIds);
      st.requests.set(event.requestId, { rowIds, startSeq: st.seq, overflow: false, remapped: false, log: 0 });
      for (const row of rowIds) st.rowRequest.set(row, event.requestId);
      return { emits: out };
    }
    case "fetchAnswer": {
      const limited = handleFetchAnswer(c, event);
      finish(c, "fetch");
      return { emits: out, limited };
    }
    case "fetchFail": {
      const req = st.requests.get(event.requestId);
      if (req) {
        st.requests.delete(event.requestId);
        for (const row of req.rowIds) if (st.rowRequest.get(row) === event.requestId) st.rowRequest.delete(row);
      }
      return { emits: out };
    }
    case "propChange":
      handlePropChange(c, event.next);
      return { emits: out };
    case "remove": {
      const removed = handleRemove(c, event.rowIds);
      finish(c, "remove");
      return { emits: out, removed };
    }
    case "evict":
      handleEvict(c, event);
      return { emits: out };
    case "idSwap":
      handleIdSwap(c, event.map);
      finish(c, "id-swap");
      return { emits: out };
    case "invalidateRows": {
      if (event.rowIds === null) st.fetchedRows.clear();
      else for (const row of event.rowIds) st.fetchedRows.delete(row);
      for (const req of st.requests.values()) {
        if (event.rowIds === null || event.rowIds.some((row) => req.rowIds.has(row))) req.remapped = true;
      }
      return { emits: out };
    }
    case "expire": {
      for (const [id, tomb] of st.tombstones) if (tomb.expiresAt <= event.now) st.tombstones.delete(id);
      for (const [id, at] of st.ownConfirmedAt) if (event.now - at >= OWN_WRITE_GRACE_MS) st.ownConfirmedAt.delete(id);
      if (st.controlled) reconcileEmitted(c);
      return { emits: out };
    }
  }
}

/** The confirmed records as `next` for `onCommentsChange`; records the add-on did not change keep the app's original objects. */

import { createStore, type StoreApi } from "zustand/vanilla";
import { reduce } from "./comment-reducer";
import { createCommentsState, type CommentEvent, type CommentsState, type ReduceResult } from "./comment-state";
import type { Bounds } from "./validate";

export type OpenTarget = { rowId: string; columnId: string; by: "keyboard" | "pointer" | "menu"; nonce: number };

/** The numeric channels the UI subscribes to. `revision` moves with comment content, `draftRevision` with drafts and conflicts only. */
export type CommentUiState = {
  revision: number;
  draftRevision: number;
  open: OpenTarget | null;
  announcement: { text: string; nonce: number };
};

export type CommentStore = {
  core: CommentsState;
  ui: StoreApi<CommentUiState>;
  /** Row ids of the rendered, non-hole rows; a plain field so reporting never renders. */
  visibleRowIds: readonly string[];
  setVisibleRowIds(ids: readonly string[]): void;
  onVisibleChange: (() => void) | null;
  dispatch(event: CommentEvent): ReduceResult;
  bumpDrafts(): void;
  bumpContent(): void;
  open(target: { rowId: string; columnId: string }, by: OpenTarget["by"]): void;
  close(): void;
  announce(text: string): void;
};

const QUIET_EVENTS = new Set<CommentEvent["type"]>(["fetchStart", "invalidateRows"]);

export function createCommentStore(bounds: Bounds, controlled: boolean): CommentStore {
  const core = createCommentsState(bounds, controlled);
  const ui = createStore<CommentUiState>(() => ({ revision: 0, draftRevision: 0, open: null, announcement: { text: "", nonce: 0 } }));
  let nonce = 0;
  const store: CommentStore = {
    core,
    ui,
    visibleRowIds: [],
    onVisibleChange: null,
    setVisibleRowIds(ids) {
      store.visibleRowIds = ids;
      store.onVisibleChange?.();
    },
    dispatch(event) {
      const seqBefore = core.seq;
      const result = reduce(core, event);
      const idle = event.type === "propChange" || event.type === "expire" || event.type === "remote";
      if (!QUIET_EVENTS.has(event.type) && (!idle || core.seq !== seqBefore)) ui.setState((s) => ({ revision: s.revision + 1, draftRevision: s.draftRevision + 1 }));
      return result;
    },
    bumpDrafts() {
      ui.setState((s) => ({ draftRevision: s.draftRevision + 1 }));
    },
    bumpContent() {
      ui.setState((s) => ({ revision: s.revision + 1, draftRevision: s.draftRevision + 1 }));
    },
    open(target, by) {
      nonce += 1;
      ui.setState({ open: { rowId: target.rowId, columnId: target.columnId, by, nonce } });
    },
    close() {
      if (ui.getState().open !== null) ui.setState({ open: null });
    },
    announce(text) {
      ui.setState((s) => ({ announcement: { text, nonce: s.announcement.nonce + 1 } }));
    },
  };
  return store;
}

import type { CommentStore } from "./comment-store";
import type { ReduceResult, CommentEvent } from "./comment-state";
import type { CellComment, UseDataGridCommentsOptions } from "./types";
import { validateComment, type Bounds } from "./validate";

export const FETCH_DEBOUNCE_MS = 150;
export const FETCH_BATCH = 200;
export const FETCH_IN_FLIGHT = 2;
export const FETCH_RETRY_GAP_MS = 2000;
export const FETCH_TIMEOUT_MS = 30_000;
export const MAX_FETCH_ANSWER = 10_000;
const MAX_FAILED_ROWS = 10_000;

export type FetchState = "idle" | "loading" | "failed" | "ready";

export type FetchDeps = {
  store: CommentStore;
  controlled: boolean;
  now(): number;
  optionsOf(): UseDataGridCommentsOptions;
  dispatch(event: CommentEvent): ReduceResult;
  refreshBounds(): Bounds;
  isBusy(rowId: string): boolean;
  isDisposed(): boolean;
  warn(key: string, message: string): void;
  callSafely(fn: () => void): void;
};

export type FetchScheduler = {
  schedule(): void;
  onVisibleChange(): void;
  /** Marks rows (or every row) unfetched and loads the rendered ones again. */
  refetch(rowIds: readonly string[] | null): void;
  clearFailed(rowIds: readonly string[]): void;
  remapRows(map: ReadonlyMap<string, string>): void;
  fetchState(rowId: string): FetchState;
  retryFetch(rowId: string): void;
  dispose(): void;
};

/** Loads the comments of the rendered rows through `fetchComments`: debounced, batched, bounded, and retried. */
export function createFetchScheduler(deps: FetchDeps): FetchScheduler {
  const { store, now, optionsOf, dispatch, refreshBounds, isBusy, isDisposed, warn, callSafely } = deps;
  const core = store.core;
  const failedRows = new Set<string>();
  const failedAt = new Map<string, number>();
  const recency = new Map<string, number>();
  const controllers = new Map<number, { controller: AbortController; timer: ReturnType<typeof setTimeout> }>();
  const retryHalf = new Map<string, number>();
  let requestSeq = 0;
  let inFlight = 0;
  let debounce: ReturnType<typeof setTimeout> | null = null;
  let retryTimer: ReturnType<typeof setTimeout> | null = null;

  const unfetchedVisible = (): string[] => {
    const ts = now();
    const rows: string[] = [];
    for (const row of store.visibleRowIds) {
      if (core.fetchedRows.has(row) || core.rowRequest.has(row) || isBusy(row)) continue;
      if (failedRows.has(row)) continue;
      const failed = failedAt.get(row);
      if (failed !== undefined && ts - failed < FETCH_RETRY_GAP_MS) continue;
      rows.push(row);
    }
    return rows;
  };

  function schedule(): void {
    if (isDisposed() || !optionsOf().fetchComments) return;
    if (debounce !== null) clearTimeout(debounce);
    debounce = setTimeout(() => {
      debounce = null;
      runFetches();
    }, FETCH_DEBOUNCE_MS);
  }

  function runFetches(): void {
    const fetcher = optionsOf().fetchComments;
    if (isDisposed() || !fetcher) return;
    const rows = unfetchedVisible();
    let cursor = 0;
    while (inFlight < FETCH_IN_FLIGHT && cursor < rows.length) {
      let size = FETCH_BATCH;
      for (const row of rows.slice(cursor, cursor + FETCH_BATCH)) size = Math.min(size, retryHalf.get(row) ?? FETCH_BATCH);
      const batch = rows.slice(cursor, cursor + Math.max(1, size));
      cursor += batch.length;
      startFetch(fetcher, batch);
    }
  }

  function noteFailure(rowIds: readonly string[], reason: "error" | "limit"): void {
    const ts = now();
    for (const row of rowIds) failedAt.set(row, ts);
    while (failedAt.size > MAX_FAILED_ROWS) {
      const oldest = failedAt.keys().next().value;
      if (oldest === undefined) break;
      failedAt.delete(oldest);
    }
    if (reason !== "limit") return;
    if (rowIds.length === 1) failedRows.add(rowIds[0] as string);
    else for (const row of rowIds) retryHalf.set(row, Math.max(1, Math.floor(rowIds.length / 2)));
  }

  function applyAnswer(requestId: number, rowIds: string[], answer: readonly unknown[]): void {
    const bounds = refreshBounds();
    const rawIds = new Set<string>();
    const records: CellComment[] = [];
    let invalid = 0;
    for (const raw of answer) {
      let id: unknown;
      try {
        id = (raw as { id?: unknown } | null)?.id;
      } catch {
        id = undefined;
      }
      if (typeof id === "string") rawIds.add(id);
      const valid = validateComment(raw, bounds);
      if (valid) records.push(valid);
      else invalid += 1;
    }
    if (invalid > 0) warn("fetch-invalid", `${invalid} fetched record(s) were dropped (invalid)`);
    for (const row of rowIds) {
      failedAt.delete(row);
      retryHalf.delete(row);
    }
    const result = dispatch({ type: "fetchAnswer", requestId, records, rawIds, now: now() });
    if (result.limited) {
      const handler = optionsOf().onFetchError;
      if (handler) callSafely(() => handler({ reason: "limit", rowIds }));
    }
    evictIfNeeded();
    store.bumpContent();
    schedule();
  }

  function startFetch(fetcher: NonNullable<UseDataGridCommentsOptions["fetchComments"]>, rowIds: string[]): void {
    requestSeq += 1;
    const requestId = requestSeq;
    const controller = new AbortController();
    inFlight += 1;
    dispatch({ type: "fetchStart", requestId, rowIds });
    store.bumpContent();
    let finished = false;
    const finish = (): boolean => {
      if (finished) return false;
      finished = true;
      const entry = controllers.get(requestId);
      if (entry) clearTimeout(entry.timer);
      controllers.delete(requestId);
      inFlight -= 1;
      return true;
    };
    const fail = (error: unknown, reason: "error" | "limit"): void => {
      if (!finish()) return;
      dispatch({ type: "fetchFail", requestId });
      noteFailure(rowIds, reason);
      store.bumpContent();
      const handler = optionsOf().onFetchError;
      if (handler) callSafely(() => handler({ reason, rowIds, error }));
      if (!isDisposed()) {
        if (retryTimer !== null) clearTimeout(retryTimer);
        retryTimer = setTimeout(schedule, FETCH_RETRY_GAP_MS);
      }
    };
    const settleAborted = (): void => {
      if (finish()) dispatch({ type: "fetchFail", requestId });
    };
    const timer = setTimeout(() => {
      controller.abort();
      fail(new Error("comments fetch timed out"), "error");
    }, FETCH_TIMEOUT_MS);
    controllers.set(requestId, { controller, timer });
    let promise: Promise<readonly CellComment[]>;
    try {
      promise = Promise.resolve(fetcher({ rowIds, signal: controller.signal }));
    } catch (error) {
      fail(error, "error");
      return;
    }
    promise.then(
      (answer) => {
        if (finished || isDisposed() || controller.signal.aborted) return settleAborted();
        if (!Array.isArray(answer)) return fail(new Error("fetchComments must resolve to an array"), "error");
        if (answer.length > MAX_FETCH_ANSWER) return fail(undefined, "limit");
        finish();
        applyAnswer(requestId, rowIds, answer);
      },
      (error: unknown) => {
        if (isDisposed() || controller.signal.aborted) return settleAborted();
        fail(error, "error");
      },
    );
  }

  function evictIfNeeded(): void {
    if (deps.controlled) return;
    const limit = refreshBounds().maxCachedRows;
    if (core.index.size <= limit) return;
    const visible = new Set(store.visibleRowIds);
    const open = store.ui.getState().open;
    if (open) visible.add(open.rowId);
    const candidates: string[] = [];
    let over = core.index.size - limit;
    for (const row of recency.keys()) {
      if (over <= 0) break;
      if (visible.has(row) || !core.index.has(row)) continue;
      candidates.push(row);
      over -= 1;
    }
    if (candidates.length === 0) return;
    dispatch({ type: "evict", rowIds: candidates, keepRows: visible });
    for (const row of candidates) if (!core.index.has(row)) recency.delete(row);
  }

  function abortUnrendered(): void {
    const visible = new Set(store.visibleRowIds);
    for (const [requestId, req] of core.requests) {
      let any = false;
      for (const row of req.rowIds) if (visible.has(row)) any = true;
      if (any) continue;
      controllers.get(requestId)?.controller.abort();
    }
  }

  return {
    schedule,
    onVisibleChange() {
      for (const row of store.visibleRowIds) {
        recency.delete(row);
        recency.set(row, now());
      }
      const recencyCap = Math.max(refreshBounds().maxCachedRows * 4, 4000);
      while (recency.size > recencyCap) {
        const oldest = recency.keys().next().value;
        if (oldest === undefined) break;
        recency.delete(oldest);
      }
      abortUnrendered();
      schedule();
    },
    refetch(rowIds) {
      if (rowIds) for (const row of rowIds) failedRows.delete(row);
      else failedRows.clear();
      dispatch({ type: "invalidateRows", rowIds });
      store.bumpContent();
      schedule();
    },
    clearFailed(rowIds) {
      for (const row of rowIds) failedRows.delete(row);
    },
    remapRows(map) {
      for (const [oldId, newId] of map) {
        if (failedRows.delete(oldId)) failedRows.add(newId);
        if (recency.delete(oldId)) recency.set(newId, now());
      }
    },
    fetchState(rowId) {
      if (!optionsOf().fetchComments) return "ready";
      if (core.fetchedRows.has(rowId)) return "ready";
      if (failedRows.has(rowId) || (failedAt.has(rowId) && !core.rowRequest.has(rowId))) return "failed";
      return core.rowRequest.has(rowId) ? "loading" : "idle";
    },
    retryFetch(rowId) {
      failedRows.delete(rowId);
      failedAt.delete(rowId);
      retryHalf.delete(rowId);
      store.bumpContent();
      schedule();
    },
    dispose() {
      if (debounce !== null) clearTimeout(debounce);
      if (retryTimer !== null) clearTimeout(retryTimer);
      debounce = null;
      retryTimer = null;
      for (const { controller, timer } of controllers.values()) {
        clearTimeout(timer);
        controller.abort();
      }
      controllers.clear();
    },
  };
}

import { isDev, isThenable } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  cellComments,
  confirmedSnapshot,
  discardConflict,
  discardDraft,
  editDraftKey,
  MAX_REMOTE_BATCH,
  newDraftKey,
  putDraft,
  type AckOutcome,
  type Conflict,
  type Draft,
  type Emit,
} from "./comment-state";
import { createFetchScheduler } from "./comment-fetch";
import { createCommentStore, type CommentStore } from "./comment-store";
import { createWriteIdGenerator, defaultCreateId } from "./create-id";
import { resolveCommentsLabels } from "./labels";
import type {
  ApplyRemoteVerdict,
  CellComment,
  CommentAction,
  CommentAuthor,
  CommentChange,
  CommentRejectedCtx,
  CommentRejectReason,
  OrphanedCommentsCtx,
  UseDataGridCommentsOptions,
} from "./types";
import { cleanText, isSafeId, parseSaveAnswer, resolveBounds, validateAuthor, validateChange, type Bounds } from "./validate";

const MAX_BUSY_ROWS = 10_000;
const EXPIRE_INTERVAL_MS = 60_000;

/** What the engine needs to know about the grid it is mounted in; the Mount component supplies it. */
export type GridAdapter = {
  readOnly(): boolean;
  /** `"saving"` while the row's `onSave` promise is pending. */
  saveStatus(rowId: string): string | undefined;
  /** Scrolls to the cell, makes it active, and opens the popover once the cell renders; `false` for a hole, a filtered-out row, or a hidden column. */
  open(ref: { rowId: string; columnId: string }, by: "keyboard" | "pointer" | "menu"): boolean;
};

export type WriteResult =
  | { ok: true; settled: Promise<void> }
  | { ok: false; reason: CommentRejectReason | "pending" };

export type WriteBase = { version: number; writeId: string | undefined };

type WriteSpec = {
  action: CommentAction;
  rowId: string;
  columnId: string;
  id?: string;
  text?: string;
  base?: WriteBase;
  reuse?: Conflict;
  forceBase?: number;
};

export type CommentEngine = {
  store: CommentStore;
  attachGrid(adapter: GridAdapter | null): () => void;
  bounds(): Bounds;
  applyRemote(changes: readonly CommentChange[]): ApplyRemoteVerdict;
  getComments(): readonly CellComment[];
  removeComments(rowIds: readonly string[]): number;
  refetch(rowIds?: readonly string[]): void;
  syncProp(next: readonly CellComment[]): void;
  create(input: { rowId: string; columnId: string; text: string }): Promise<WriteResult>;
  edit(id: string, text: string, base?: WriteBase): Promise<WriteResult>;
  remove(id: string, base?: WriteBase): Promise<WriteResult>;
  setResolved(id: string, resolved: boolean, base?: WriteBase): Promise<WriteResult>;
  retry(id: string, text?: string): Promise<WriteResult>;
  saveMine(id: string, text: string): Promise<WriteResult>;
  discard(id: string): void;
  setDraft(draft: Omit<Draft, "key"> & { key?: string }): void;
  discardDraft(key: string): void;
  isRowBusy(rowId: string): boolean;
  fetchState(rowId: string): "idle" | "loading" | "failed" | "ready";
  retryFetch(rowId: string): void;
  observeDataChange(next: readonly unknown[], change: import("@/registry/default/components/data-grid/data-grid").DataChange<unknown>, ctx: { getRowId(row: unknown, index: number): string }): void;
  kickFetch(): void;
  noteRowsRendered(rowIds: readonly string[]): void;
  currentUser(): CommentAuthor | null;
  openComments(ref: { rowId: string; columnId: string }, by?: "keyboard" | "pointer" | "menu"): boolean;
  start(): void;
  dispose(): void;
};

export type EngineConfig = {
  getOptions(): UseDataGridCommentsOptions;
  now?: () => number;
  initialComments?: readonly CellComment[];
  controlled: boolean;
};

function createWarnOnce(): (key: string, message: string) => void {
  const warned = new Set<string>();
  return (key, message) => {
    if (!isDev() || warned.has(key)) return;
    warned.add(key);
    console.warn(`[data-grid-comments] ${message}`);
  };
}

function callSafely(fn: () => void): void {
  try {
    fn();
  } catch (error) {
    if (isDev()) console.error("[data-grid-comments] a callback threw", error);
  }
}

export function createCommentEngine(config: EngineConfig): CommentEngine {
  const now = config.now ?? (() => Date.now());
  const optionsOf = (): UseDataGridCommentsOptions => config.getOptions();
  const initial = optionsOf();
  let bounds = resolveBounds(initial);
  const store = createCommentStore(bounds, config.controlled);
  const core = store.core;
  const nextWriteId = createWriteIdGenerator();
  const warnOnce = createWarnOnce();
  let grid: GridAdapter | null = null;
  let disposed = false;
  const busyRows = new Set<string>();
  const gateControllers = new Map<string, AbortController>();

  const refreshBounds = (): Bounds => {
    const next = resolveBounds(optionsOf());
    if (next.maxTextLength !== bounds.maxTextLength || next.maxCommentsPerCell !== bounds.maxCommentsPerCell || next.maxComments !== bounds.maxComments || next.maxCachedRows !== bounds.maxCachedRows) {
      bounds = next;
      core.bounds = next;
    }
    return bounds;
  };

  // --- callbacks --------------------------------------------------------------------------------

  const queue: Emit[] = [];
  let firing = false;

  const handleEmit = (emit: Emit): void => {
    const o = optionsOf();
    switch (emit.t) {
      case "change": {
        noteRemoteAdded(emit);
        if (o.onCommentsChange) {
          const handler = o.onCommentsChange;
          const next = confirmedSnapshot(core);
          callSafely(() => handler(next, { changes: emit.changes, source: emit.source }));
        }
        return;
      }
      case "local":
        if (o.onLocalChange) {
          const handler = o.onLocalChange;
          callSafely(() => handler(emit.change));
        }
        return;
      case "rejected":
        if (o.onCommentRejected) {
          const handler = o.onCommentRejected;
          callSafely(() => handler(emit.ctx));
        }
        return;
      case "refetch":
        fetcher.clearFailed(emit.rowIds);
        fetcher.schedule();
        return;
      case "warn":
        warnOnce(emit.message, emit.message);
    }
  };

  const fire = (emits: readonly Emit[]): void => {
    queue.push(...emits);
    if (firing) return;
    firing = true;
    try {
      for (let emit = queue.shift(); emit !== undefined; emit = queue.shift()) handleEmit(emit);
    } finally {
      firing = false;
    }
  };

  function noteRemoteAdded(emit: Extract<Emit, { t: "change" }>): void {
    if (emit.source !== "remote" && emit.source !== "fetch") return;
    const open = store.ui.getState().open;
    if (!open) return;
    for (const change of emit.changes) {
      if (change.kind !== "upsert") continue;
      const c = change.comment;
      if (c.rowId !== open.rowId || c.columnId !== open.columnId) continue;
      if (c.version !== 1) continue;
      const labels = resolveCommentsLabels(optionsOf().labels);
      store.announce(labels.announceAdded(c.author.name ?? labels.unknownAuthor));
      return;
    }
  }

  const dispatch = (event: Parameters<CommentStore["dispatch"]>[0]) => {
    const result = store.dispatch(event);
    fire(result.emits);
    return result;
  };

  // --- seed and prop ----------------------------------------------------------------------------

  if (config.initialComments && config.initialComments.length > 0) {
    dispatch({ type: "propChange", next: config.initialComments, now: 0 });
    if (!config.controlled) {
      core.propRaw = new Map();
      core.rawOf = new Map();
    }
    if (core.dropped > 0) warnOnce("seed-dropped", `${core.dropped} seed record(s) were dropped (invalid or over a bound)`);
  }

  let expireTimer: ReturnType<typeof setInterval> | null = null;
  const startExpire = (): void => {
    if (expireTimer !== null || typeof setInterval === "undefined") return;
    expireTimer = setInterval(() => dispatch({ type: "expire", now: now() }), EXPIRE_INTERVAL_MS);
  };

  // --- busy rows --------------------------------------------------------------------------------

  function isBusy(rowId: string): boolean {
    if (!busyRows.has(rowId)) return false;
    if (grid?.saveStatus(rowId) === "saving") return true;
    busyRows.delete(rowId);
    return false;
  }

  const fetcher = createFetchScheduler({
    store,
    controlled: config.controlled,
    now,
    optionsOf,
    dispatch,
    refreshBounds,
    isBusy,
    isDisposed: () => disposed,
    warn: warnOnce,
    callSafely,
  });
  store.onVisibleChange = fetcher.onVisibleChange;

  // --- writes -----------------------------------------------------------------------------------

  function validatedUser(): CommentAuthor | null {
    const user = optionsOf().currentUser;
    return user ? validateAuthor(user) : null;
  }

  function writeIsBlocked(rowId: string): CommentRejectReason | null {
    const o = optionsOf();
    if (grid?.readOnly() && !o.allowWhenReadOnly) return "read-only";
    if (!validatedUser()) return "invalid";
    if (isBusy(rowId)) return "row-busy";
    return null;
  }

  function rejectBeforeWrite(action: CommentAction, reason: CommentRejectReason, change?: CommentChange, message?: string): WriteResult {
    const handler = optionsOf().onCommentRejected;
    if (handler) {
      const ctx: CommentRejectedCtx = { action, reason };
      if (change) ctx.change = change;
      if (message) ctx.message = message;
      callSafely(() => handler(ctx));
    }
    return { ok: false, reason };
  }

  const gateKey = (spec: WriteSpec): string => spec.id ?? newDraftKey(spec.rowId, spec.columnId);

  async function runGate(spec: WriteSpec, user: CommentAuthor, prev: CellComment | undefined): Promise<boolean | "error"> {
    const o = optionsOf();
    const key = gateKey(spec);
    gateControllers.get(key)?.abort();
    const controller = new AbortController();
    gateControllers.set(key, controller);
    try {
      let verdict: boolean | Promise<boolean>;
      if (spec.action === "create") {
        verdict = o.canCreate ? o.canCreate({ rowId: spec.rowId, columnId: spec.columnId, user, signal: controller.signal }) : true;
      } else {
        const comment = prev as CellComment;
        if (spec.action === "update" || spec.action === "delete") {
          const gate = spec.action === "update" ? o.canEdit : o.canDelete;
          verdict = gate ? gate({ comment, user, signal: controller.signal }) : comment.author.id === user.id;
        } else {
          verdict = o.canResolve ? o.canResolve({ comment, user, signal: controller.signal }) : true;
        }
      }
      const result = isThenable(verdict) ? await verdict : verdict;
      if (controller.signal.aborted && disposed) return false;
      return result === true;
    } catch {
      return "error";
    } finally {
      if (gateControllers.get(key) === controller) gateControllers.delete(key);
    }
  }

  async function execute(spec: WriteSpec): Promise<WriteResult> {
    const o = optionsOf();
    refreshBounds();
    const prev = spec.id ? core.confirmed.get(spec.id) : undefined;
    if (spec.action !== "create" && !prev) return { ok: false, reason: "invalid" };
    if (spec.id && core.pending.has(spec.id)) return { ok: false, reason: "pending" };
    const blocked = writeIsBlocked(spec.rowId);
    if (blocked) return rejectBeforeWrite(spec.action, blocked);
    const user = validatedUser() as CommentAuthor;

    let id = spec.id;
    if (spec.action === "create") {
      try {
        id = spec.reuse ? spec.reuse.id : (o.createId ?? defaultCreateId)();
      } catch {
        return rejectBeforeWrite("create", "error");
      }
      if (!isSafeId(id) || core.confirmed.has(id) || core.tombstones.has(id) || core.pending.has(id)) return rejectBeforeWrite("create", "invalid");
    }
    const commentId = id as string;

    let text: string | undefined;
    if (spec.text !== undefined) {
      if (spec.text.length > bounds.maxTextLength * 4) return rejectBeforeWrite(spec.action, "limit");
      let normalized = spec.text;
      if (o.normalizeText) {
        try {
          normalized = o.normalizeText(spec.text);
        } catch {
          return rejectBeforeWrite(spec.action, "error");
        }
      }
      text = cleanText(normalized);
      if (text.length < 1) return rejectBeforeWrite(spec.action, "invalid");
      if (text.length > bounds.maxTextLength) return rejectBeforeWrite(spec.action, "limit");
    }

    const verdict = await runGate({ ...spec, id: spec.action === "create" ? undefined : commentId }, user, prev);
    if (disposed) return { ok: false, reason: "error" };
    if (verdict === "error") return rejectBeforeWrite(spec.action, "error");
    if (verdict === false) return rejectBeforeWrite(spec.action, "forbidden");

    // after the await: re-read the store and re-check
    const blockedLate = writeIsBlocked(spec.rowId);
    if (blockedLate) return rejectBeforeWrite(spec.action, blockedLate);
    const userNow = validatedUser() as CommentAuthor;
    const confirmedNow = core.confirmed.get(commentId);
    if (spec.action !== "create" && !confirmedNow) return rejectBeforeWrite(spec.action, "invalid");
    if (core.pending.has(commentId)) return { ok: false, reason: "pending" };
    if (spec.action === "create" && (core.confirmed.has(commentId) || core.tombstones.has(commentId))) return rejectBeforeWrite("create", "invalid");

    const ts = now();
    const writeId = spec.reuse ? spec.reuse.writeId : nextWriteId();
    const baseVersion = spec.reuse ? spec.reuse.baseVersion : (spec.forceBase ?? confirmedNow?.version ?? 0);
    const base = confirmedNow;
    let record: CellComment;
    let change: CommentChange;
    if (spec.reuse) {
      record = spec.reuse.record;
      change = spec.reuse.change;
    } else if (spec.action === "create") {
      record = Object.freeze({ id: commentId, rowId: spec.rowId, columnId: spec.columnId, text: text as string, author: userNow, createdAt: ts, updatedAt: ts, version: 1, writeId, resolved: false });
      change = Object.freeze({ kind: "upsert" as const, comment: record, baseVersion: 0 });
    } else if (spec.action === "delete") {
      record = base as CellComment;
      change = Object.freeze({ kind: "delete" as const, id: commentId, rowId: record.rowId, columnId: record.columnId, version: baseVersion + 1, writeId, baseVersion });
    } else {
      const source = base as CellComment;
      const next: CellComment = { ...source, updatedAt: ts, version: baseVersion + 1, writeId };
      if (spec.action === "update") next.text = text as string;
      else if (spec.action === "resolve") {
        next.resolved = true;
        next.resolvedBy = userNow;
        next.resolvedAt = ts;
      } else {
        next.resolved = false;
        delete next.resolvedBy;
        delete next.resolvedAt;
      }
      record = Object.freeze(next);
      change = Object.freeze({ kind: "upsert" as const, comment: record, baseVersion });
    }

    // the draft base against the confirmed record: a mismatch is a stale conflict, never an overwrite
    if (spec.base && base && !spec.reuse && (spec.base.version !== base.version || spec.base.writeId !== base.writeId)) {
      const stale: Conflict = {
        id: commentId,
        rowId: record.rowId,
        columnId: record.columnId,
        action: spec.action,
        reason: "stale",
        writeId,
        baseVersion,
        baseWriteId: base.writeId,
        change,
        record,
        thrown: false,
        text: spec.action === "update" ? text : undefined,
        shownVersion: base.version,
        discardOnly: false,
      };
      core.conflicts.set(commentId, stale);
      if (text !== undefined && spec.action === "update") {
        putDraft(core, { key: editDraftKey(commentId), kind: "edit", commentId, rowId: record.rowId, columnId: record.columnId, text, baseVersion: spec.base.version, baseWriteId: spec.base.writeId });
      }
      store.bumpDrafts();
      return rejectBeforeWrite(spec.action, "stale", change);
    }

    const applied = dispatch({ type: "localWrite", action: spec.action, change, record, baseWriteId: base?.writeId, now: ts });
    if (!applied.ok) return rejectBeforeWrite(spec.action, "limit", change);
    if (spec.action === "create") discardDraft(core, newDraftKey(spec.rowId, spec.columnId));
    else if (spec.action === "update") discardDraft(core, editDraftKey(commentId));

    const settled = settleWrite(spec.action, commentId, writeId, change, base);
    return { ok: true, settled };
  }

  function settleWrite(action: CommentAction, id: string, writeId: string, change: CommentChange, prev: CellComment | undefined): Promise<void> {
    const o = optionsOf();
    const settle = (outcome: AckOutcome): void => {
      dispatch({ type: "ack", id, writeId, outcome, now: now() });
    };
    if (!o.onCommentSave) {
      settle({ kind: "void", server: false });
      return Promise.resolve();
    }
    let result: unknown;
    try {
      result = o.onCommentSave({ action, change, prev });
    } catch (error) {
      settle({ kind: "throw", error });
      return Promise.resolve();
    }
    if (!isThenable(result)) {
      settle(parseSaveAnswer(result, refreshBounds()));
      return Promise.resolve();
    }
    return (result as Promise<unknown>).then(
      (value) => settle(parseSaveAnswer(value, refreshBounds())),
      (error: unknown) => settle({ kind: "throw", error }),
    );
  }

  // --- observer ---------------------------------------------------------------------------------

  const observeDataChange: CommentEngine["observeDataChange"] = (next, change, ctx) => {
    if (disposed) return;
    if (change.source === "id-swap") {
      const rowIndex = new Map<unknown, number>();
      next.forEach((row, i) => rowIndex.set(row, i));
      const map = new Map<string, string>();
      for (const op of change.ops) {
        if (op.type !== "update") continue;
        const index = rowIndex.get(op.row);
        if (index === undefined) continue;
        const newId = ctx.getRowId(op.row, index);
        if (newId !== op.rowId) map.set(op.rowId, newId);
      }
      if (map.size === 0) return;
      for (const [oldId, newId] of map) if (busyRows.delete(oldId)) busyRows.add(newId);
      fetcher.remapRows(map);
      const open = store.ui.getState().open;
      dispatch({ type: "idSwap", map });
      if (open && map.has(open.rowId)) store.ui.setState({ open: { ...open, rowId: map.get(open.rowId) as string } });
      return;
    }
    const deleted: string[] = [];
    for (const op of change.ops) {
      if (op.type === "insert") {
        if (grid?.saveStatus(op.rowId) === "saving" && busyRows.size < MAX_BUSY_ROWS) busyRows.add(op.rowId);
      } else if (op.type === "delete") {
        busyRows.delete(op.rowId);
        if (core.index.has(op.rowId)) deleted.push(op.rowId);
      }
    }
    if (deleted.length === 0) return;
    const comments: CellComment[] = [];
    for (const rowId of deleted) {
      const columns = core.index.get(rowId);
      if (!columns) continue;
      for (const [columnId] of columns) for (const entry of cellComments(core, rowId, columnId)) comments.push(entry.comment);
    }
    if (comments.length === 0) return;
    const handler = optionsOf().onOrphanedComments;
    if (handler) {
      const ctxOut: OrphanedCommentsCtx = { comments, rowIds: deleted, source: change.source };
      callSafely(() => handler(ctxOut));
    }
  };

  const engine: CommentEngine = {
    store,
    attachGrid(adapter) {
      grid = adapter;
      return () => {
        if (grid === adapter) grid = null;
      };
    },
    bounds: () => bounds,
    applyRemote(changes) {
      const b = refreshBounds();
      const list = Array.isArray(changes) ? changes : [];
      const batch = list.slice(0, MAX_REMOTE_BATCH);
      const valid: { index: number; change: CommentChange }[] = [];
      const invalid: number[] = [];
      batch.forEach((raw, index) => {
        const change = validateChange(raw, b);
        if (change) valid.push({ index, change });
        else invalid.push(index);
      });
      if (invalid.length > 0) warnOnce("remote-invalid", `${invalid.length} remote change(s) were dropped (invalid)`);
      const result = dispatch({ type: "remote", changes: valid, invalid, truncated: Math.max(0, list.length - batch.length), now: now() });
      return result.verdict as ApplyRemoteVerdict;
    },
    getComments() {
      return confirmedSnapshot(core).slice(0, bounds.maxComments);
    },
    removeComments(rowIds) {
      const list = rowIds.slice(0, MAX_REMOTE_BATCH);
      const open = store.ui.getState().open;
      const result = dispatch({ type: "remove", rowIds: list, now: now() });
      if (open && list.includes(open.rowId)) store.close();
      return result.removed ?? 0;
    },
    refetch(rowIds) {
      fetcher.refetch(rowIds ? rowIds.slice(0, MAX_REMOTE_BATCH) : null);
    },
    syncProp(next) {
      refreshBounds();
      dispatch({ type: "propChange", next, now: now() });
      if (core.dropped > 0) warnOnce("prop-dropped", `${core.dropped} record(s) of the comments prop were dropped (invalid or over a bound)`);
    },
    create: (input) => execute({ action: "create", rowId: input.rowId, columnId: input.columnId, text: input.text }),
    edit: (id, text, base) => {
      const c = core.confirmed.get(id);
      return c ? execute({ action: "update", id, rowId: c.rowId, columnId: c.columnId, text, base }) : Promise.resolve({ ok: false as const, reason: "invalid" as const });
    },
    remove: (id, base) => {
      const c = core.confirmed.get(id);
      return c ? execute({ action: "delete", id, rowId: c.rowId, columnId: c.columnId, base }) : Promise.resolve({ ok: false as const, reason: "invalid" as const });
    },
    setResolved: (id, resolved, base) => {
      const c = core.confirmed.get(id);
      return c ? execute({ action: resolved ? "resolve" : "reopen", id, rowId: c.rowId, columnId: c.columnId, base }) : Promise.resolve({ ok: false as const, reason: "invalid" as const });
    },
    retry(id, text) {
      const conflict = core.conflicts.get(id);
      if (!conflict) return Promise.resolve({ ok: false as const, reason: "invalid" as const });
      const unchanged = conflict.text === undefined || text === undefined || text === conflict.text;
      discardConflict(core, id);
      store.bumpDrafts();
      if (conflict.thrown && unchanged) {
        const spec: WriteSpec = { action: conflict.action, id: conflict.action === "create" ? undefined : id, rowId: conflict.rowId, columnId: conflict.columnId, reuse: conflict };
        return execute(spec);
      }
      return execute({
        action: conflict.action,
        id: conflict.action === "create" ? undefined : id,
        rowId: conflict.rowId,
        columnId: conflict.columnId,
        text: text ?? conflict.text,
        base: conflict.action === "create" ? undefined : { version: conflict.baseVersion, writeId: conflict.baseWriteId },
      });
    },
    saveMine(id, text) {
      const conflict = core.conflicts.get(id);
      if (!conflict) return Promise.resolve({ ok: false as const, reason: "invalid" as const });
      discardConflict(core, id);
      store.bumpDrafts();
      const base = core.confirmed.get(id);
      return execute({
        action: conflict.action,
        id: conflict.action === "create" ? undefined : id,
        rowId: conflict.rowId,
        columnId: conflict.columnId,
        text,
        forceBase: conflict.shownVersion ?? base?.version,
      });
    },
    discard(id) {
      const conflict = core.conflicts.get(id);
      discardConflict(core, id);
      if (conflict) {
        discardDraft(core, conflict.action === "create" ? newDraftKey(conflict.rowId, conflict.columnId) : editDraftKey(id));
      }
      store.bumpDrafts();
    },
    setDraft(draft) {
      putDraft(core, { ...draft, key: draft.key ?? (draft.kind === "new" ? newDraftKey(draft.rowId, draft.columnId) : editDraftKey(draft.commentId as string)) });
      store.bumpDrafts();
    },
    discardDraft(key) {
      discardDraft(core, key);
      store.bumpDrafts();
    },
    isRowBusy: isBusy,
    fetchState: (rowId) => fetcher.fetchState(rowId),
    retryFetch: (rowId) => fetcher.retryFetch(rowId),
    observeDataChange,
    kickFetch: () => fetcher.schedule(),
    noteRowsRendered(rowIds) {
      store.setVisibleRowIds(rowIds);
    },
    currentUser: validatedUser,
    openComments: (ref, by = "pointer") => grid?.open(ref, by) ?? false,
    start() {
      disposed = false;
      startExpire();
      store.onVisibleChange = fetcher.onVisibleChange;
      fetcher.schedule();
    },
    dispose() {
      disposed = true;
      fetcher.dispose();
      if (expireTimer !== null) clearInterval(expireTimer);
      expireTimer = null;
      for (const controller of gateControllers.values()) controller.abort();
      gateControllers.clear();
      store.onVisibleChange = null;
    },
  };
  return engine;
}

"use client";

import { memo, useLayoutEffect, useMemo, type ComponentType, type CSSProperties, type ReactNode } from "react";
import { useStore } from "zustand";
import { useShallow } from "zustand/react/shallow";
import { useDataGridVisibleColumns, type OverlayPluginCtx } from "@/registry/default/components/data-grid/data-grid";
import { GRID_LAYER, hasAnyPin, rowIdAtViewRow, useDataGridSelector } from "@/registry/default/components/data-grid/data-grid-sdk";
import { cellComments } from "./comment-state";
import type { CommentEngine } from "./comment-engine";
import type { UseDataGridCommentsOptions } from "./types";

export const MAX_MARKERS = 2048;

type Marker = { key: string; rowId: string; columnId: string; viewRow: number; col: number; unresolved: boolean };

type MarkerProps = {
  marker: Marker;
  windowStart: number;
  colOffset: number;
  pinStyle: CSSProperties | undefined;
  onOpen: (rowId: string, columnId: string) => void;
};

const CommentMarker = memo(function CommentMarker({ marker, windowStart, colOffset, pinStyle, onOpen }: MarkerProps) {
  return (
    <div
      data-grid-comment-marker-cell=""
      data-pinned={pinStyle ? "" : undefined}
      className="pointer-events-none"
      style={{
        // out of flow when unpinned, so a marker change never re-lays out the rows canvas
        position: "absolute",
        inset: 0,
        gridColumnStart: marker.col + colOffset,
        gridColumnEnd: marker.col + colOffset + 1,
        gridRowStart: marker.viewRow - windowStart + 1,
        gridRowEnd: marker.viewRow - windowStart + 2,
        // one step above the active cell it marks, so a pinned cell still covers an unpinned marker
        zIndex: (pinStyle ? GRID_LAYER.activePinnedCell : GRID_LAYER.activeCell) + 1,
        ...(pinStyle ? { inset: undefined, ...pinStyle } : {}),
      }}
    >
      <span
        aria-hidden="true"
        data-grid-comment-marker=""
        data-unresolved={marker.unresolved ? "" : undefined}
        className="pointer-events-auto absolute end-0 top-0 block size-2 cursor-pointer pointer-coarse:size-6"
        onClick={(event) => {
          event.stopPropagation();
          onOpen(marker.rowId, marker.columnId);
        }}
        onPointerDown={(event) => event.stopPropagation()}
        onDoubleClick={(event) => event.stopPropagation()}
      >
        <span
          className={`pointer-events-none absolute end-0 top-0 block size-2 ${
            marker.unresolved
              ? "bg-primary [clip-path:polygon(0_0,100%_0,100%_100%)] rtl:[clip-path:polygon(0_0,100%_0,0_100%)] forced-colors:bg-[Highlight]"
              : "rounded-full border border-primary forced-colors:border-[CanvasText]"
          }`}
        />
      </span>
    </div>
  );
});

/** Walks the rendered rows once; only rows with comments read their cells. `revision` keys the memo on the mutable add-on state. */
function computeMarkers(
  core: CommentEngine["store"]["core"],
  rowIds: readonly (string | undefined)[],
  columnIndex: ReadonlyMap<string, number>,
  hideResolved: boolean,
  firstViewRow: number,
  revision: number,
): Marker[] {
  const list: Marker[] = [];
  if (revision < 0) return list;
  for (let i = 0; i < rowIds.length && list.length < MAX_MARKERS; i += 1) {
    const rowId = rowIds[i];
    if (rowId === undefined) continue;
    const columns = core.index.get(rowId);
    if (!columns) continue;
    for (const columnId of columns.keys()) {
      const col = columnIndex.get(columnId);
      if (col === undefined) continue;
      const entries = cellComments(core, rowId, columnId);
      if (entries.length === 0) continue;
      const unresolved = entries.some((e) => !e.comment.resolved);
      if (!unresolved && hideResolved) continue;
      list.push({ key: `${rowId}\u0001${columnId}`, rowId, columnId, viewRow: firstViewRow + i, col, unresolved });
      if (list.length >= MAX_MARKERS) break;
    }
  }
  return list;
}

/** The Overlay component of the plugin, closed over the engine. */
export function createCommentsOverlay(engine: CommentEngine, getOptions: () => UseDataGridCommentsOptions): ComponentType<OverlayPluginCtx> {
  function CommentsOverlay(ctx: OverlayPluginCtx): ReactNode {
    const { windowStart, clampRowStart, clampRowEnd, colOffset, pinTrack, splitRectByPinZones } = ctx;
    const revision = useStore(engine.store.ui, (s) => s.revision);
    const visibleColumns = useDataGridVisibleColumns();
    const rowIds = useDataGridSelector<unknown, readonly (string | undefined)[]>(
      useShallow((s) => {
        const ids: (string | undefined)[] = [];
        for (let viewRow = clampRowStart; viewRow < clampRowEnd; viewRow += 1) ids.push(rowIdAtViewRow(s, viewRow));
        return ids;
      }),
    );
    useLayoutEffect(() => {
      engine.noteRowsRendered(rowIds.filter((id): id is string => id !== undefined));
    }, [rowIds]);

    const hideResolved = getOptions().hideResolved === true;
    const columnIndex = useMemo(() => new Map(visibleColumns.map((c, i) => [c.id, i])), [visibleColumns]);

    const markers = useMemo(
      () => computeMarkers(engine.store.core, rowIds, columnIndex, hideResolved, clampRowStart, revision),
      [rowIds, columnIndex, hideResolved, clampRowStart, revision],
    );

    const onOpen = useMemo(() => (rowId: string, columnId: string) => void engine.openComments({ rowId, columnId }, "pointer"), []);

    return (
      <>
        {markers.map((marker) => {
          const segments = hasAnyPin(pinTrack) ? splitRectByPinZones({ x: marker.col, y: marker.viewRow, width: 1, height: 1 }, pinTrack) : [{ rect: { x: marker.col, y: marker.viewRow, width: 1, height: 1 }, pinStyle: undefined }];
          const segment = segments[0];
          if (!segment) return null;
          return (
            <CommentMarker
              key={marker.key}
              marker={marker}
              windowStart={windowStart}
              colOffset={colOffset}
              pinStyle={"pinStyle" in segment ? segment.pinStyle : undefined}
              onOpen={onOpen}
            />
          );
        })}
      </>
    );
  }
  return CommentsOverlay;
}

"use client";

import { useEffect, useState, type ComponentType, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { useStore } from "zustand";
import { useDataGridActiveCell, useDataGridApi, useDataGridKeymap, useDataGridReadOnly, type DataGridApi } from "@/registry/default/components/data-grid/data-grid";
import { GRID_ATTR, isDev, rowIdAtViewRow, useDataGridContainer } from "@/registry/default/components/data-grid/data-grid-sdk";
import { CommentPopoverHost } from "./comment-popover";
import { cellComments } from "./comment-state";
import type { CommentEngine, GridAdapter } from "./comment-engine";
import { resolveCommentsLabels } from "./labels";
import type { UseDataGridCommentsOptions } from "./types";

const ANNOUNCE_DEBOUNCE_MS = 250;
const OPEN_WAIT_FRAMES = 10;

function humanizeChord(binding: string | undefined): string {
  if (!binding) return "";
  return binding
    .split("+")
    .map((part) => (part.length > 1 ? part.charAt(0).toUpperCase() + part.slice(1) : part.toUpperCase()))
    .join("+");
}

/** Empties the live region before each message so a repeated text is read again. */
function createSpeaker(setText: (text: string) => void) {
  let timer: ReturnType<typeof setTimeout> | null = null;
  return {
    say(message: string): void {
      setText("");
      if (timer !== null) clearTimeout(timer);
      timer = setTimeout(() => setText(message), 30);
    },
    dispose(): void {
      if (timer !== null) clearTimeout(timer);
    },
  };
}

function Announcer({ engine, getOptions }: { engine: CommentEngine; getOptions: () => UseDataGridCommentsOptions }): ReactNode {
  const api = useDataGridApi();
  const scrollRef = useDataGridContainer();
  const activeCell = useDataGridActiveCell();
  const keymap = useDataGridKeymap();
  const announcement = useStore(engine.store.ui, (s) => s.announcement);
  const revision = useStore(engine.store.ui, (s) => s.revision);
  const [text, setText] = useState("");
  const [mounted, setMounted] = useState(false);
  const [speaker] = useState(() => createSpeaker(setText));
  const [last] = useState(() => ({ key: "" }));
  const chord = humanizeChord(keymap["openComments"]?.[0]);

  useEffect(() => setMounted(true), []);
  useEffect(() => () => speaker.dispose(), [speaker]);

  useEffect(() => {
    if (announcement.nonce > 0 && announcement.text) speaker.say(announcement.text);
  }, [announcement, speaker]);

  useEffect(() => {
    if (!activeCell) return;
    const timer = setTimeout(() => {
      const scroll = scrollRef.current;
      const focus = document.activeElement;
      const inside = focus !== null && ((scroll?.contains(focus) ?? false) || focus.closest(`[${GRID_ATTR.commentsPopup}]`) !== null);
      if (!inside) return;
      const state = api.store.getState();
      const rowId = rowIdAtViewRow(state, activeCell.row);
      const columnId = state.visibleColumns[activeCell.col]?.id;
      if (rowId === undefined || columnId === undefined) return;
      const entries = cellComments(engine.store.core, rowId, columnId);
      if (entries.length === 0) {
        last.key = "";
        return;
      }
      const key = `${rowId}\u0001${columnId}`;
      if (last.key === key) return;
      last.key = key;
      const unresolved = entries.filter((e) => !e.comment.resolved).length;
      const labels = resolveCommentsLabels(getOptions().labels);
      speaker.say(labels.announce(entries.length, unresolved, chord));
    }, ANNOUNCE_DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [activeCell, revision, api, engine, scrollRef, getOptions, speaker, last, chord]);

  if (!mounted || typeof document === "undefined") return null;
  return createPortal(
    <div role="status" aria-live="polite" aria-atomic="true" className="sr-only" data-grid-comments-announcer="">
      {text}
    </div>,
    document.body,
  );
}

function findCell(scroll: HTMLElement | null, viewRow: number, columnId: string): boolean {
  return scroll?.querySelector(`[${GRID_ATTR.rowIndex}="${viewRow}"] [data-column-id="${CSS.escape(columnId)}"]`) != null;
}

function waitForCell(engine: CommentEngine, scroll: HTMLElement | null, viewRow: number, ref: { rowId: string; columnId: string }, by: "keyboard" | "pointer" | "menu", frame: number): void {
  if (findCell(scroll, viewRow, ref.columnId)) {
    engine.store.open(ref, by);
    return;
  }
  if (frame >= OPEN_WAIT_FRAMES) {
    if (isDev()) console.warn("[data-grid-comments] openComments dropped: the cell did not render within 10 frames");
    return;
  }
  requestAnimationFrame(() => waitForCell(engine, scroll, viewRow, ref, by, frame + 1));
}

/** Scrolls to the cell, makes it active, and opens the popover once the cell renders. */
function openCell(
  engine: CommentEngine,
  api: DataGridApi<unknown>,
  scroll: HTMLElement | null,
  ref: { rowId: string; columnId: string },
  by: "keyboard" | "pointer" | "menu",
): boolean {
  const state = api.store.getState();
  if (!state.visibleColumns.some((c) => c.id === ref.columnId)) return false;
  const viewRow = api.getViewRowIds().indexOf(ref.rowId);
  if (viewRow < 0) return false;
  api.scrollTo(ref);
  api.actions.selectCell(ref);
  waitForCell(engine, scroll, viewRow, ref, by, 0);
  return true;
}

function assignReadOnly(state: { readOnly: boolean }, readOnly: boolean): void {
  state.readOnly = readOnly;
}

/** The plugin's Mount component: grid adapter, save-status watcher, announcer, popover host. */
export function createCommentsMount(engine: CommentEngine, getOptions: () => UseDataGridCommentsOptions): ComponentType {
  function CommentsMount(): ReactNode {
    const api = useDataGridApi();
    const scrollRef = useDataGridContainer();
    const readOnly = useDataGridReadOnly();
    const [gridState] = useState(() => ({ readOnly: false }));

    useEffect(() => {
      assignReadOnly(gridState, readOnly);
    }, [gridState, readOnly]);

    useEffect(() => {
      const adapter: GridAdapter = {
        readOnly: () => gridState.readOnly,
        saveStatus: (rowId) => api.store.getState().saveStatus.get(rowId),
        open: (ref, by) => openCell(engine, api, scrollRef.current, ref, by),
      };
      return engine.attachGrid(adapter);
    }, [api, scrollRef, gridState]);

    useEffect(() => {
      let previous = api.store.getState().saveStatus;
      return api.store.subscribe((s) => {
        if (s.saveStatus === previous) return;
        previous = s.saveStatus;
        engine.kickFetch();
      });
    }, [api]);

    return (
      <>
        <CommentPopoverHost engine={engine} getOptions={getOptions} />
        <Announcer engine={engine} getOptions={getOptions} />
      </>
    );
  }
  return CommentsMount;
}

"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { useCallback, useEffect, useMemo, useState, type KeyboardEvent, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { useStore } from "zustand";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { useDataGridApi, useDataGridReadOnly } from "@/registry/default/components/data-grid/data-grid";
import { GRID_ATTR, isComposingKey, rowIdAtViewRow, toSafeText, useDataGridContainer } from "@/registry/default/components/data-grid/data-grid-sdk";
import { cellComments, editDraftKey, newDraftKey } from "./comment-state";
import type { CommentEngine, WriteResult } from "./comment-engine";
import { resolveCommentsLabels, type DataGridCommentsLabels } from "./labels";
import type { CellComment, CommentAuthor, UseDataGridCommentsOptions } from "./types";

const FALLBACK_COLOR = "var(--color-primary)";

function safeColor(color: string | undefined): string {
  if (!color) return FALLBACK_COLOR;
  if (typeof CSS === "undefined" || typeof CSS.supports !== "function") return color;
  return CSS.supports("color", color) ? color : FALLBACK_COLOR;
}

function focusableIn(root: HTMLElement): HTMLElement[] {
  return Array.from(root.querySelectorAll<HTMLElement>("button, textarea, input, [href], [tabindex]:not([tabindex='-1'])")).filter(
    (el) => el.getAttribute("aria-disabled") !== "true" && !(el as HTMLButtonElement).disabled,
  );
}

type Locate = () => HTMLElement | null;
type Holder<T> = { current: T };

function setHolder<T>(holder: Holder<T>, value: T): void {
  holder.current = value;
}

/** The cell's rect, or the last known one while the cell is out of the rendered rows. */
function rectOf(cell: HTMLElement | null, last: Holder<DOMRect | null>): DOMRect {
  if (cell) last.current = cell.getBoundingClientRect();
  return last.current ?? new DOMRect();
}

/** A mutable holder that is not a React ref: popup and field elements are read by event handlers and Base UI callbacks, never during render. */
function useHolder<T>(initial: T): Holder<T> {
  return useState(() => ({ current: initial }))[0];
}

/** Finds the rendered cell element of `{ rowId, columnId }`; the view row is cached and re-resolved when the store moved the row. */
function createCellAnchor(locate: Locate, getScroll: () => HTMLElement | null, last: Holder<DOMRect | null>) {
  return {
    get contextElement() {
      return getScroll() ?? undefined;
    },
    getBoundingClientRect: () => rectOf(locate(), last),
  };
}

function useLocateCell(rowId: string, columnId: string): Locate {
  const api = useDataGridApi();
  const scrollRef = useDataGridContainer();
  const viewRowCache = useHolder(-1);
  return useCallback(() => {
    const scroll = scrollRef.current;
    if (!scroll) return null;
    const state = api.store.getState();
    let viewRow = viewRowCache.current;
    if (viewRow < 0 || rowIdAtViewRow(state, viewRow) !== rowId) {
      viewRow = api.getViewRowIds().indexOf(rowId);
      setHolder(viewRowCache, viewRow);
    }
    if (viewRow < 0) return null;
    return scroll.querySelector<HTMLElement>(`[${GRID_ATTR.rowIndex}="${viewRow}"] [data-column-id="${CSS.escape(columnId)}"]`);
  }, [api, scrollRef, rowId, columnId, viewRowCache]);
}

/** The active row stays mounted off-window, so a mounted cell is not enough: it must also overlap the scrollport. */
function isCellInView(cell: HTMLElement | null, scroll: HTMLElement | null): boolean {
  if (!cell) return false;
  if (!scroll) return true;
  const c = cell.getBoundingClientRect();
  const v = scroll.getBoundingClientRect();
  return c.bottom > v.top && c.top < v.bottom && c.right > v.left && c.left < v.right;
}

type HostProps = { engine: CommentEngine; getOptions: () => UseDataGridCommentsOptions };

/** Mounts the popover for the open target. */
export function CommentPopoverHost({ engine, getOptions }: HostProps): ReactNode {
  const open = useStore(engine.store.ui, (s) => s.open);
  if (!open || typeof document === "undefined") return null;
  // portaled to the body: Base UI leaves an aria-owns span where it renders, and inside role="grid" that span fails the required-children rule
  return createPortal(<OpenPopover key={open.nonce} engine={engine} getOptions={getOptions} rowId={open.rowId} columnId={open.columnId} by={open.by} />, document.body);
}

function OpenPopover({ engine, getOptions, rowId, columnId, by }: HostProps & { rowId: string; columnId: string; by: "keyboard" | "pointer" | "menu" }): ReactNode {
  const api = useDataGridApi();
  const scrollRef = useDataGridContainer();
  const locate = useLocateCell(rowId, columnId);
  const getScroll = useCallback(() => scrollRef.current, [scrollRef]);
  const popupEl = useHolder<HTMLDivElement | null>(null);
  const composerEl = useHolder<HTMLTextAreaElement | null>(null);
  const escapeFn = useHolder<(() => boolean) | null>(null);
  const lastRect = useHolder<DOMRect | null>(null);
  const options = getOptions();
  const labels = resolveCommentsLabels(options.labels);

  // a function anchor: Base UI builds the virtual element outside render, where it reads the scroll element
  const anchor = useCallback(() => createCellAnchor(locate, getScroll, lastRect), [locate, getScroll, lastRect]);

  const closeWithFocusGrid = useCallback(
    (reason: "scroll-out" | "tab") => {
      const popup = popupEl.current;
      const hadFocus = popup !== null && popup.contains(document.activeElement);
      engine.store.close();
      if (!hadFocus) return;
      if (reason === "tab") api.focus();
      else scrollRef.current?.focus({ preventScroll: true });
    },
    [api, engine, scrollRef, popupEl],
  );

  useEffect(() => {
    const scroll = scrollRef.current;
    let frame = 0;
    const check = (): void => {
      frame = 0;
      if (!isCellInView(locate(), scroll)) closeWithFocusGrid("scroll-out");
    };
    const schedule = (): void => {
      if (frame === 0) frame = requestAnimationFrame(check);
    };
    scroll?.addEventListener("scroll", schedule, { passive: true });
    const unsubscribe = api.store.subscribe(schedule);
    schedule();
    return () => {
      scroll?.removeEventListener("scroll", schedule);
      unsubscribe();
      if (frame !== 0) cancelAnimationFrame(frame);
    };
  }, [api, closeWithFocusGrid, locate, scrollRef]);

  const columnTitle = useMemo(() => {
    const column = api.store.getState().visibleColumns.find((c) => c.id === columnId);
    if (!column) return columnId;
    return column.headerText ?? (typeof column.header === "string" ? column.header : column.id);
  }, [api, columnId]);
  const [cellText, setCellText] = useState("");
  useEffect(() => {
    setCellText((locate()?.textContent ?? "").trim().slice(0, 60));
  }, [locate]);

  return (
    <PopoverPrimitive.Root
      open
      modal={false}
      onOpenChange={(next, details) => {
        if (next) return;
        if (details.reason === "escape-key" && escapeFn.current?.()) {
          details.cancel();
          return;
        }
        engine.store.close();
      }}
    >
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Positioner anchor={anchor} side="bottom" align="start" sideOffset={4} className="isolate z-50">
          <PopoverPrimitive.Popup
            ref={popupEl}
            tabIndex={-1}
            aria-label={labels.popover(columnTitle, cellText)}
            {...{ [GRID_ATTR.commentsPopup]: "", [GRID_ATTR.keepFocus]: "" }}
            initialFocus={() => (cellComments(engine.store.core, rowId, columnId).length === 0 ? (composerEl.current ?? popupEl.current) : popupEl.current)}
            finalFocus={() => {
              const active = document.activeElement;
              const free = !active || active === document.body || (by !== "pointer" && popupEl.current?.contains(active)) === true;
              if (free) api.focus();
              return false;
            }}
            onKeyDown={(event: KeyboardEvent<HTMLDivElement>) => {
              if (event.key !== "Tab" || isComposingKey(event)) return;
              const popup = popupEl.current;
              if (!popup) return;
              const items = focusableIn(popup);
              const first = items[0];
              const last = items[items.length - 1];
              const active = document.activeElement;
              if ((event.shiftKey && (active === first || active === popup)) || (!event.shiftKey && active === last)) closeWithFocusGrid("tab");
            }}
            className={cn(
              "z-50 flex max-h-96 w-80 origin-(--transform-origin) flex-col gap-2.5 overflow-y-auto rounded-lg bg-popover p-2.5 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-hidden data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
              options.className,
            )}
          >
            <PopoverBody engine={engine} getOptions={getOptions} rowId={rowId} columnId={columnId} labels={labels} composerEl={composerEl} escapeFn={escapeFn} />
          </PopoverPrimitive.Popup>
        </PopoverPrimitive.Positioner>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  );
}

type BodyProps = {
  engine: CommentEngine;
  getOptions: () => UseDataGridCommentsOptions;
  rowId: string;
  columnId: string;
  labels: DataGridCommentsLabels;
  composerEl: Holder<HTMLTextAreaElement | null>;
  escapeFn: Holder<(() => boolean) | null>;
};

function noticeFor(result: WriteResult, labels: DataGridCommentsLabels): string {
  if (result.ok) return "";
  switch (result.reason) {
    case "forbidden":
      return labels.refused;
    case "row-busy":
      return labels.rowBusyHint;
    case "read-only":
      return labels.readOnlyHint;
    case "pending":
      return "";
    default:
      return labels.failed;
  }
}

function formatTime(ts: number, locale: string): string {
  try {
    return new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short" }).format(new Date(ts));
  } catch {
    return new Date(ts).toISOString();
  }
}

function authorName(author: CommentAuthor, labels: DataGridCommentsLabels): string {
  return author.name ?? labels.unknownAuthor;
}

/** The add-on state is mutable; both revisions are inputs here so the compiler re-reads it when either moves. */
function readBody(engine: CommentEngine, getOptions: () => UseDataGridCommentsOptions, rowId: string, columnId: string, revision: number, draftRevision: number) {
  return {
    options: getOptions(),
    user: engine.currentUser(),
    entries: cellComments(engine.store.core, rowId, columnId),
    fetchState: engine.fetchState(rowId),
    busy: engine.isRowBusy(rowId),
    stamp: revision + draftRevision,
  };
}

function readDraft(core: CommentEngine["store"]["core"], key: string, draftRevision: number) {
  return draftRevision < 0 ? undefined : core.drafts.get(key);
}

function findComposeConflict(core: CommentEngine["store"]["core"], rowId: string, columnId: string, draftRevision: number) {
  if (draftRevision < 0) return undefined;
  return Array.from(core.conflicts.values()).find((c) => c.rowId === rowId && c.columnId === columnId && (c.action === "create" || !core.confirmed.has(c.id)));
}

function PopoverBody({ engine, getOptions, rowId, columnId, labels, composerEl, escapeFn }: BodyProps): ReactNode {
  const revision = useStore(engine.store.ui, (s) => s.revision);
  const draftRevision = useStore(engine.store.ui, (s) => s.draftRevision);
  const core = engine.store.core;
  const gridReadOnly = useDataGridReadOnly();
  const { options, user, entries, fetchState, busy } = readBody(engine, getOptions, rowId, columnId, revision, draftRevision);
  const writable = user !== null && (!gridReadOnly || options.allowWhenReadOnly === true);
  const [confirmId, setConfirmId] = useState<string | null>(null);
  const [notice, setNotice] = useState("");
  const composeKey = newDraftKey(rowId, columnId);
  const composeDraft = readDraft(core, composeKey, draftRevision);
  const composeConflict = findComposeConflict(core, rowId, columnId, draftRevision);
  const rootEl = useHolder<HTMLDivElement | null>(null);
  const focusedInside = useHolder(false);

  useEffect(() => {
    setHolder(escapeFn, () => {
      if (confirmId === null) return false;
      setConfirmId(null);
      return true;
    });
    return () => setHolder(escapeFn, null);
  }, [confirmId, escapeFn]);

  useEffect(() => {
    const popup = rootEl.current?.closest<HTMLElement>(`[${GRID_ATTR.commentsPopup}]`) ?? null;
    if (confirmId !== null) rootEl.current?.querySelector<HTMLElement>("[data-comment-confirm]")?.focus();
    else if (focusedInside.current && (!document.activeElement || document.activeElement === document.body)) popup?.focus();
  }, [confirmId, rootEl, focusedInside]);

  useEffect(() => {
    if (!focusedInside.current) return;
    if (document.activeElement && document.activeElement !== document.body) return;
    rootEl.current?.closest<HTMLElement>(`[${GRID_ATTR.commentsPopup}]`)?.focus();
  });

  const run = async (promise: Promise<WriteResult>): Promise<void> => {
    const result = await promise;
    setNotice(noticeFor(result, labels));
  };

  const submitCompose = (): void => {
    const text = composeDraft?.text ?? "";
    if (!text.trim()) return;
    void run(engine.create({ rowId, columnId, text })).then(() => composerEl.current?.focus());
  };

  const hasCustomGate = (name: "canEdit" | "canDelete"): boolean => options[name] !== undefined;
  const canShowEdit = (c: CellComment): boolean => writable && (hasCustomGate("canEdit") || c.author.id === user?.id);
  const canShowDelete = (c: CellComment): boolean => writable && (hasCustomGate("canDelete") || c.author.id === user?.id);
  const max = engine.bounds().maxTextLength;
  const anySaving = entries.some((e) => e.saving);

  return (
    <div
      ref={rootEl}
      className="flex flex-col gap-2"
      aria-busy={anySaving || undefined}
      onFocusCapture={() => setHolder(focusedInside, true)}
    >
      {fetchState === "loading" || fetchState === "idle" ? (
        <p role="status" aria-live="polite" className="text-muted-foreground">
          {labels.loading}
        </p>
      ) : null}
      {fetchState === "failed" ? (
        <div role="alert" className="flex items-center justify-between gap-2">
          <span>{labels.loadFailed}</span>
          <Button type="button" size="xs" variant="outline" onClick={() => engine.retryFetch(rowId)}>
            {labels.retry}
          </Button>
        </div>
      ) : null}
      {entries.length === 0 && fetchState === "ready" ? <p className="text-muted-foreground">{labels.noComments}</p> : null}
      {entries.length > 0 ? (
        <ul role="list" aria-label={labels.commentList} className="flex flex-col gap-2">
          {entries.map(({ comment, saving }, index) => {
            const time = formatTime(comment.createdAt, labels.locale);
            const name = authorName(comment.author, labels);
            const editDraft = core.drafts.get(editDraftKey(comment.id));
            const conflict = core.conflicts.get(comment.id);
            const disabled = saving;
            return (
              <li key={comment.id} className="flex flex-col gap-1.5">
                {index > 0 ? <Separator /> : null}
                <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                  <span aria-hidden="true" className="size-2 shrink-0 rounded-full" style={{ backgroundColor: safeColor(comment.author.color) }} />
                  <bdi className="font-medium text-foreground">{name}</bdi>
                  <time dateTime={new Date(comment.createdAt).toISOString()}>{time}</time>
                  {comment.resolved ? <span>{labels.resolved}</span> : null}
                  {saving ? <span role="status">{labels.saving}</span> : null}
                </div>
                {editDraft ? (
                  <EditBox
                    engine={engine}
                    comment={comment}
                    text={editDraft.text}
                    base={{ version: editDraft.baseVersion, writeId: editDraft.baseWriteId }}
                    labels={labels}
                    max={max}
                    disabled={disabled}
                    onResult={(result) => setNotice(noticeFor(result, labels))}
                  />
                ) : (
                  <p className="text-sm">
                    <bdi className="whitespace-pre-wrap [overflow-wrap:anywhere]">{toSafeText(comment.text)}</bdi>
                  </p>
                )}
                {conflict ? <ConflictBox engine={engine} conflictId={comment.id} labels={labels} onResult={(result) => setNotice(noticeFor(result, labels))} /> : null}
                {!editDraft ? (
                  <div className="flex flex-wrap gap-1">
                    {canShowEdit(comment) ? (
                      <Button
                        type="button"
                        size="xs"
                        variant="ghost"
                        aria-disabled={disabled || undefined}
                        aria-label={labels.edit(name, time)}
                        onClick={() => {
                          if (disabled) return;
                          engine.setDraft({ kind: "edit", commentId: comment.id, rowId, columnId, text: comment.text, baseVersion: comment.version, baseWriteId: comment.writeId });
                        }}
                      >
                        {labels.editAction}
                      </Button>
                    ) : null}
                    {canShowDelete(comment) ? (
                      confirmId === comment.id ? (
                        <>
                          <Button
                            type="button"
                            size="xs"
                            variant="destructive"
                            data-comment-confirm=""
                            aria-disabled={disabled || undefined}
                            aria-label={labels.confirmRemove(name, time)}
                            onClick={() => {
                              if (disabled) return;
                              setConfirmId(null);
                              void run(engine.remove(comment.id, { version: comment.version, writeId: comment.writeId }));
                            }}
                          >
                            {labels.confirmDeleteAction}
                          </Button>
                          <Button type="button" size="xs" variant="ghost" onClick={() => setConfirmId(null)}>
                            {labels.cancel}
                          </Button>
                        </>
                      ) : (
                        <Button type="button" size="xs" variant="ghost" aria-disabled={disabled || undefined} aria-label={labels.remove(name, time)} onClick={() => !disabled && setConfirmId(comment.id)}>
                          {labels.deleteAction}
                        </Button>
                      )
                    ) : null}
                    {writable ? (
                      <Button
                        type="button"
                        size="xs"
                        variant="ghost"
                        aria-disabled={disabled || undefined}
                        aria-label={comment.resolved ? labels.reopen(name, time) : labels.resolve(name, time)}
                        onClick={() => !disabled && void run(engine.setResolved(comment.id, !comment.resolved, { version: comment.version, writeId: comment.writeId }))}
                      >
                        {comment.resolved ? labels.reopenAction : labels.resolveAction}
                      </Button>
                    ) : null}
                  </div>
                ) : null}
              </li>
            );
          })}
        </ul>
      ) : null}
      {notice ? (
        <p role="alert" className="text-destructive">
          {notice}
        </p>
      ) : null}
      {composeConflict ? <ConflictBox engine={engine} conflictId={composeConflict.id} labels={labels} onResult={(result) => setNotice(noticeFor(result, labels))} /> : null}
      {fetchState === "ready" ? (
        writable && !busy ? (
          <div className="flex flex-col gap-1.5">
            <Textarea
              ref={composerEl}
              aria-label={labels.composer}
              placeholder={labels.composerPlaceholder}
              maxLength={max}
              value={composeDraft?.text ?? ""}
              className="min-h-16"
              onChange={(event) => engine.setDraft({ kind: "new", rowId, columnId, text: event.target.value, baseVersion: 0, baseWriteId: undefined })}
              onKeyDown={(event) => {
                if (event.key === "Enter" && (event.ctrlKey || event.metaKey) && !isComposingKey(event)) {
                  event.preventDefault();
                  submitCompose();
                }
              }}
            />
            <div className="flex items-center justify-between gap-2">
              <span className="text-xs text-muted-foreground">{(composeDraft?.text.length ?? 0) > max * 0.8 ? labels.counter(composeDraft?.text.length ?? 0, max) : ""}</span>
              <Button type="button" size="sm" onClick={submitCompose}>
                {labels.submit}
              </Button>
            </div>
          </div>
        ) : (
          <p className="text-muted-foreground">{busy ? labels.rowBusyHint : user === null ? labels.noUserHint : labels.readOnlyHint}</p>
        )
      ) : null}
    </div>
  );
}

function EditBox({
  engine,
  comment,
  text,
  base,
  labels,
  max,
  disabled,
  onResult,
}: {
  engine: CommentEngine;
  comment: CellComment;
  text: string;
  base: { version: number; writeId: string | undefined };
  labels: DataGridCommentsLabels;
  max: number;
  disabled: boolean;
  onResult: (result: WriteResult) => void;
}): ReactNode {
  useStore(engine.store.ui, (s) => s.draftRevision);
  const submit = (): void => {
    if (disabled || !text.trim()) return;
    void engine.edit(comment.id, text, base).then(onResult);
  };
  return (
    <div className="flex flex-col gap-1.5">
      <Textarea
        autoFocus
        aria-label={labels.composer}
        maxLength={max}
        value={text}
        onChange={(event) => engine.setDraft({ kind: "edit", commentId: comment.id, rowId: comment.rowId, columnId: comment.columnId, text: event.target.value, baseVersion: base.version, baseWriteId: base.writeId })}
        onKeyDown={(event) => {
          if (event.key === "Enter" && (event.ctrlKey || event.metaKey) && !isComposingKey(event)) {
            event.preventDefault();
            submit();
          }
        }}
      />
      <div className="flex gap-1">
        <Button type="button" size="xs" aria-disabled={disabled || undefined} onClick={submit}>
          {labels.save}
        </Button>
        <Button type="button" size="xs" variant="ghost" onClick={() => engine.discardDraft(editDraftKey(comment.id))}>
          {labels.cancel}
        </Button>
      </div>
    </div>
  );
}

function ConflictBox({ engine, conflictId, labels, onResult }: { engine: CommentEngine; conflictId: string; labels: DataGridCommentsLabels; onResult: (result: WriteResult) => void }): ReactNode {
  const revision = useStore(engine.store.ui, (s) => s.draftRevision);
  const conflict = revision < 0 ? undefined : engine.store.core.conflicts.get(conflictId);
  if (!conflict) return null;
  const gone = conflict.action !== "create" && !engine.store.core.confirmed.has(conflict.id);
  const draftKey = conflict.action === "create" || gone ? newDraftKey(conflict.rowId, conflict.columnId) : editDraftKey(conflict.id);
  const draftText = engine.store.core.drafts.get(draftKey)?.text ?? conflict.text;
  const message = conflict.reason === "stale" ? labels.changedByOther : conflict.reason === "forbidden" ? labels.refused : labels.failed;
  return (
    <div role="alert" className="flex flex-col gap-1.5 text-destructive">
      <span>{conflict.message ?? message}</span>
      <div className="flex flex-wrap gap-1">
        {conflict.reason === "stale" && !conflict.discardOnly && !gone && conflict.text !== undefined ? (
          <Button type="button" size="xs" variant="outline" onClick={() => void engine.saveMine(conflict.id, draftText ?? "").then(onResult)}>
            {labels.saveMine}
          </Button>
        ) : null}
        {conflict.reason !== "stale" && conflict.reason !== "forbidden" ? (
          <Button type="button" size="xs" variant="outline" onClick={() => void engine.retry(conflict.id, draftText).then(onResult)}>
            {labels.retry}
          </Button>
        ) : null}
        <Button type="button" size="xs" variant="ghost" onClick={() => engine.discard(conflict.id)}>
          {labels.discard}
        </Button>
      </div>
    </div>
  );
}

import type { CommentEngine } from "./comment-engine";
import { resolveCommentsLabels } from "./labels";
import type { CommentMenuItem, CommentMenuItemsResolver, UseDataGridCommentsOptions } from "./types";

/** Appends a "Comments…" item to the cell menu. The popover opens on the next frame, after the menu has closed and returned focus. */
export function createMenuItemsResolver(engine: CommentEngine, getOptions: () => UseDataGridCommentsOptions): CommentMenuItemsResolver {
  return function getCommentMenuItems<TItem extends { id: string }>(
    ctx: { rowId: string; columnId: string; viewRowIndex: number },
    defaults: TItem[],
  ): (TItem | CommentMenuItem)[] {
    const label = resolveCommentsLabels(getOptions().labels).menuItem;
    const separator = { id: "sep-comments", separator: true } as unknown as TItem;
    const item: CommentMenuItem = {
      id: "comments",
      label,
      onClick: () => {
        requestAnimationFrame(() => {
          engine.openComments({ rowId: ctx.rowId, columnId: ctx.columnId }, "menu");
        });
      },
    };
    return [...defaults, separator, item];
  };
}
